// [v3.18.0 NETWORK/WDT] Workerzy Telegram/Firebase moga legalnie blokowac sie
// w TCP/TLS/HTTP dluzej niz 15 s. Nie subskrybujemy ich do per-task TWDT;
// Core 1 (loopTask) obserwuje ponizsze 32-bitowe heartbeat/state bez I/O.
static volatile uint32_t g_tgTaskHeartbeatMs = 0;
static volatile uint32_t g_tgPollHeartbeatMs = 0;
static volatile uint8_t  g_tgTaskState = 0;      // 0=IDLE, 1=NETWORK
static volatile uint8_t  g_tgPollTaskState = 0;  // 0=IDLE, 1=NETWORK

static inline void tgTaskBeat(uint8_t state) {
  __atomic_store_n(&g_tgTaskState, state, __ATOMIC_RELEASE);
  __atomic_store_n(&g_tgTaskHeartbeatMs, millis(), __ATOMIC_RELEASE);
}

static inline void tgPollTaskBeat(uint8_t state) {
  __atomic_store_n(&g_tgPollTaskState, state, __ATOMIC_RELEASE);
  __atomic_store_n(&g_tgPollHeartbeatMs, millis(), __ATOMIC_RELEASE);
}


