extern String prognozaJsonCache;
unsigned long otaRestartOMillis = 0;
unsigned long terminalRestartOMillis = 0;  // [TERMINAL] patrz terminalRestartZaplanowany wyzej
unsigned long fsUploadRestartOMillis = 0;  // [LOGI-FS-UPLOAD] patrz fsUploadRestartZaplanowany wyzej
static const uint32_t WIFI_STA_TIMEOUT_PER_SIEC_MS = 6000UL;  // timeout probowania KAZDEJ zapisanej sieci z osobna
static const uint32_t WIFI_STA_RETRY_Z_AP_MS       = 30000UL; // co ile probowac wrocic do STA, gdy dzialamy w AP (= pierwszy krok tabeli WIFI_STA_RETRY_KROKI_MS ponizej)
// [FIX-WIFI-NONBLOCKING-STA, v2.12.1] Tabela kolejnych odstepow miedzy
// PELNYMI cyklami prob STA, gdy KOLEJNE cykle z rzedu koncza sie porazka
// (domowy router niedostepny dluzej niz chwile) — patrz wifiRetryBackoffIndeks
// i wifiRetryBackoffMs nizej oraz logika w wifiLoop().
// Kazdy cykl prob, nawet w wersji nieblokujacej, fizycznie zaburza kanal
// SoftAP-u (jeden radiotransceiver ESP32, patrz [DIAG-AP-STA-BLOKADA] w
// DIAGNOZA_ZAWIESZANIE_LCD_WIFI.md sekcja 3.2 oraz research:
// esp32.com/viewtopic.php?t=1192) — rzadsze cykle przy realnie dluzszej
// awarii = rzadsze, krotsze zaburzenia dla LCD, kosztem wolniejszego
// powrotu STA po odzyskaniu domowego WiFi (do 1h w najgorszym razie).
// SWIADOMIE tabela krokow, NIE czyste podwajanie (x2) az do sufitu: gesto na
// poczatku (30s-1-2-4min, jak proste x2) na krotkie zerwania, potem od razu
// 5-15-30-60min na dlugie awarie — czyste x2 od 30s dobiloby do 1h dopiero
// po 8 podwojeniach (30s,1,2,4,8,16,32,64min), zbyt wolno rosnac na starcie.
static const uint32_t WIFI_STA_RETRY_KROKI_MS[] = {
  WIFI_STA_RETRY_Z_AP_MS, // 30 s  - pierwsza proba po wejsciu w PORTAL_AP
  60000UL,                // 1 min
  120000UL,               // 2 min
  240000UL,               // 4 min
  300000UL,               // 5 min
  900000UL,               // 15 min
  1800000UL,              // 30 min
  3600000UL               // 1 h  - SUFIT (ostatni element, powtarzany po wyczerpaniu tabeli)
};
static const int WIFI_STA_RETRY_KROKI_LICZBA =
  sizeof(WIFI_STA_RETRY_KROKI_MS) / sizeof(WIFI_STA_RETRY_KROKI_MS[0]);

enum WifiStan {
  WIFI_STAN_LACZENIE_STA,
  WIFI_STAN_POLACZONY_STA,
  WIFI_STAN_PORTAL_AP
};
WifiStan wifiStan = WIFI_STAN_LACZENIE_STA;

DNSServer wifiDnsServer;
AsyncWebServer wifiWebServer(80);
bool wifiWebServerUruchomiony = false;

// ════════════════════════════════════════════════════════
// [TERMINAL] WebSocket "/ws" dla zakladki "Terminal" (serial online 1:1,
// wzorem Ryby_LED_fi_S3.cpp). ROZNICA CELOWA wzgledem Ryb: Ryby uzywaja
// DRUGIEGO AsyncWebServer na osobnym porcie 8080 (AsyncWebServer
// webserialServer(8080);) wylacznie dla /ws + /terminal. Centrala od
// [PUNKT 1 -- WiFi] ma zasade "JEDEN, WSPOLNY WEBSERWER" dla calego panelu
// (wifiWebServer, port 80) -- ta zasada ma pierwszenstwo nad kopiowaniem
// architektury Ryb 1:1, wiec wsTerminal dopina sie do ISTNIEJACEGO
// wifiWebServer (patrz wifiWebServer.addHandler(&wsTerminal) w
// wifiZarejestrujTrasy()), bez drugiego portu. Zachowanie funkcjonalne
// (live mirror logow + konsola komend) jest 1:1 z Rybami, tylko transport
// (jeden port zamiast dwoch) jest swiadomie inny.
AsyncWebSocket wsTerminal("/ws");
// Forward-deklaracje: definicje ponizej w pliku (tuz przed setup(), jak w
// Rybach), ale musza byc widoczne juz tutaj, bo wifiZarejestrujTrasy()
// (zdefiniowana przed nimi w tym pliku) wywoluje wsTerminal.onEvent(onWsEvent).
void onWsEvent(AsyncWebSocket *server, AsyncWebSocketClient *client,
               AwsEventType type, void *arg, uint8_t *data, size_t len);
void handleWsCmd(const String &rawCmd, AsyncWebSocketClient *client);

// [OTA-PANEL, ta sesja] Stan pośrednictwa OTA dla panelu — centrala jako
// jedyny most miedzy panelem (bez internetu, tylko AP) a GitHubem. Patrz
// OTA_PANEL_CALOSC.md, decyzja "centrala jako posrednik" (odrzucone:
// NAT/ip_napt na panelu — niewspierane oficjalnie w arduino-esp32 i zbyt
// energochlonne dla urzadzenia bateryjnego).
String g_panelWersjaZgloszona = "";   // ostatnia wersja, ktora PANEL zglosil przy /api/status (?panel_fw=...)
bool   g_panelOtaDostepna     = false; // true = panel powinien pobrac /panel-ota.bin przy najblizszym wybudzeniu
String g_panelOtaWersja       = "";    // docelowy tag_name, na ktory czekamy od panelu w g_panelWersjaZgloszona

// [RESET-DIAG, ta sesja] Ostatni ZGLOSZONY przez panel powod restartu
// (patrz esp_reset_reason() w main.cpp panelu, TEMAT B w
// OTA_PANEL_CALOSC.md — rozroznienie brownout/task_wdt, dzis nierozrozniane).
// Trzymamy TYLKO po to, zeby wykryc ZMIANE (i przy zmianie na cos
// nietypowego wyslac JEDNORAZOWY alert), a nie alarmowac przy kazdym z
// wielu /api/status w trakcie jednej sesji czuwania panelu (te
// powtarzaja ten sam powod, bo nie restartuje sie miedzy nimi).
String g_panelOstatniPowodRestartu = "";

// [SYNC-OTA, ta sesja — implementuje punkt 11.5 + synteza z punktu 12 w
// OTA_PANEL_CALOSC.md] Wspolny "semafor" miedzy /update (self-OTA
// centrali) i /update_panel (OTA-proxy dla panelu). Ustawiany PRZED
// kazda z dwoch operacji, sprawdzany na starcie OBU handlerow — zero
// nakladania sie self-OTA centrali (ktore zabija jej WiFi AP w trakcie
// restartu) z pobieraniem/serwowaniem firmware'u panelu. Dla
// /update_panel trzymany celowo DLUZEJ niz samo pobranie z GitHub — az
// do potwierdzenia nowej wersji przez panel w handlerze /api/status —
// bo to jednoczesnie zamyka wyscig na GET /panel-ota.bin (drugi
// /update_panel nie moze zaczac nowej rotacji pliku, dopoki panel nie
// skonczyl czytac poprzedniej).
bool otaOperacjaWTrakcie = false;
unsigned long wifiOstatniaProbaSTA = 0;
bool wifiApAktywny = false; // czy hotspot AP aktualnie stoi (niezaleznie od tego, czy STA tez dziala)

// [FIX-WIFI-NONBLOCKING-STA, v2.12.1] Stan nieblokujacej proby polaczenia
// STA — patrz wifiPolaczSTA_Krok() (kilkaset linii nizej, tuz po starym,
// juz niewolanym wifiPolaczSTA()). Zastepuje w pelni blokujacy stary
// mechanizm, patrz tag [DIAG-AP-STA-BLOKADA] w
// DIAGNOZA_ZAWIESZANIE_LCD_WIFI.md. Trzystanowy wynik (zamiast bool) —
// wolajacy (wifiLoop()/wifiSetup()) musi odroznic "jeszcze czekam" od
// "koniec, i to jak", inaczej nie da sie zbudowac nieblokujacej petli
// wolajacej.
enum WifiStaProbaWynik { STA_PROBA_TRWA, STA_PROBA_SUKCES, STA_PROBA_PORAZKA };
bool          staProbaAktywna    = false; // czy jakis KROK proby jest "w locie" (miedzy WiFi.begin() a rozstrzygnieciem)
int           staProbaIndeks     = 0;     // ktora zapisana siec (indeks w wifiSieci[]) probujemy w biezacym kroku
unsigned long staProbaStartMs    = 0;     // millis() startu biezacej proby (do liczenia WIFI_STA_TIMEOUT_PER_SIEC_MS)
// [FIX-WIFI-NONBLOCKING-STA, v2.12.1] Aktualny KROK odstepu miedzy PELNYMI
// cyklami prob w stanie PORTAL_AP — indeks w WIFI_STA_RETRY_KROKI_MS,
// przesuwany o 1 po kazdej kolejnej porazce (patrz wifiLoop()), resetowany
// do 0 po sukcesie/swiezym spadku z POLACZONY_STA. wifiRetryBackoffMs to
// tylko wygodny "podglad" wartosci w ms, pochodny z indeksu — trzymany
// osobno, zeby wifiLoop() mogl go porownywac z millis() bez odwolania do
// tabeli w kazdej iteracji.
int           wifiRetryBackoffIndeks = 0;
uint32_t      wifiRetryBackoffMs     = WIFI_STA_RETRY_KROKI_MS[0];

