  let _fbIdToken = safeStorage.get('piec_fb_token') || "";
  let _fbRefreshToken = safeStorage.get('piec_fb_ref_token') || "";
  let _cmdToken = safeStorage.get('piec_cmd_token') || DEFAULT_CMD_TOKEN;
