static bool diagStanPoprawny(const CrashDiagState& d) {
  return d.magic == RTC_DIAG_MAGIC && d.version == RTC_DIAG_VERSION;
}

static bool crashQueuePoprawna(const CrashReportQueue& q) {
  return q.magic == RTC_CRASH_QUEUE_MAGIC && q.head < 4 && q.count <= 4;
}

static void diagInicjalizujBoota(CrashDiagState& poprzedni, bool& poprzedniWazny) {
  poprzedni = rtcCrashDiag;
  poprzedniWazny = diagStanPoprawny(poprzedni);

  // Snapshot poprzedniego boota jest juz bezpiecznie skopiowany. Teraz
  // zerujemy stan BIEZACEJ sesji, zeby checkpointy i pola TWDT nie byly
  // mieszanka danych z dwoch rozruchow.
  memset((void*)&rtcCrashDiag, 0, sizeof(rtcCrashDiag));
  rtcCrashDiag.magic = RTC_DIAG_MAGIC;
  rtcCrashDiag.version = RTC_DIAG_VERSION;

  if (!crashQueuePoprawna(rtcCrashReportQueue)) {
    memset((void*)&rtcCrashReportQueue, 0, sizeof(rtcCrashReportQueue));
    rtcCrashReportQueue.magic = RTC_CRASH_QUEUE_MAGIC;
  }
}

static void diagCheckpoint(uint8_t taskId, uint16_t op, uint8_t stage, uint16_t detail = 0) {
  if (taskId < DIAG_TASK_LOOP || taskId > DIAG_TASK_HIST) return;
  const uint8_t idx = taskId - 1;
  CrashDiagTaskState snap;
  snap.op = op;
  snap.stage = stage;
  snap.reserved = 0;
  snap.detail = detail;
  snap.uptimeMs = millis();
  snap.seq = rtcCrashDiag.task[idx].seq + 1;
  snap.freeHeap = rtcCrashDiag.task[idx].freeHeap;
  snap.largestBlock = rtcCrashDiag.task[idx].largestBlock;
  snap.stackHwmWords = rtcCrashDiag.task[idx].stackHwmWords;

  // Nie odpalamy pelnych pomiarow sterty przy kazdym checkpointcie.
  // Przy wejściu w blokujaca operacje (BEFORE) pomiar jest zawsze odswiezany;
  // poza tym co 16 checkpointow daje trend bez dokladania duzego narzutu.
  if (stage == DIAG_STAGE_BEFORE || (snap.seq & 0x0Fu) == 0) {
    snap.freeHeap = ESP.getFreeHeap();
    snap.largestBlock = heap_caps_get_largest_free_block(MALLOC_CAP_8BIT);
    snap.stackHwmWords = uxTaskGetStackHighWaterMark(NULL);
  }

  rtcCrashDiag.task[idx] = snap;
  rtcCrashDiag.bootCounter = logBootCounter;
}

// [COMMIT-A] Jeden pasywny snapshot wszystkich klas pamieci oraz glowych
// taskow. Brak alokacji, brak I/O sieciowego, brak zmian automatyki.
static void diagRuntimeSnapshot() {
  g_runtimeDiag.internalFree = heap_caps_get_free_size(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
  g_runtimeDiag.internalLargest = heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);
  g_runtimeDiag.internalMinimum = heap_caps_get_minimum_free_size(MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT);

  g_runtimeDiag.psramFree = heap_caps_get_free_size(MALLOC_CAP_SPIRAM);
  g_runtimeDiag.psramLargest = heap_caps_get_largest_free_block(MALLOC_CAP_SPIRAM);
  g_runtimeDiag.psramMinimum = heap_caps_get_minimum_free_size(MALLOC_CAP_SPIRAM);

  // ESP32-S3 / IDF zwraca uxTaskGetStackHighWaterMark() w bajtach.
  g_runtimeDiag.stackHwm[DIAG_TASK_LOOP - 1] = (uint32_t)uxTaskGetStackHighWaterMark(NULL);
  g_runtimeDiag.stackHwm[DIAG_TASK_TG - 1] = tgTaskHandle ? (uint32_t)uxTaskGetStackHighWaterMark(tgTaskHandle) : 0u;
  g_runtimeDiag.stackHwm[DIAG_TASK_TGPOLL - 1] = tgPollTaskHandle ? (uint32_t)uxTaskGetStackHighWaterMark(tgPollTaskHandle) : 0u;
  g_runtimeDiag.stackHwm[DIAG_TASK_HIST - 1] = historiaTaskHandle ? (uint32_t)uxTaskGetStackHighWaterMark(historiaTaskHandle) : 0u;

  // taskCount() jest tylko odczytem kolejki AsyncClient; nie wykonuje requestu
  // Firebase i nie tworzy nowego workera. Pozwala zobaczyc ile zadan biblioteki
  // oczekuje/wykonuje sie w danym momencie (w tym zadanie auth, jesli aktywne).
  g_runtimeDiag.fbTaskCount = (uint32_t)fbAsyncClient.taskCount();
}

static bool coredumpSeqJestOczekiwanyNaWysylke(uint32_t seq);
static bool coredumpZnajdzPoSeq(uint32_t seq, String& sciezka, uint32_t& boot, size_t& rozmiar);
static bool sendTelegramCoredumpPlik(const String& sciezka, uint32_t boot, uint32_t seq);

static void diagPushCrashReport(esp_reset_reason_t reason, uint16_t streak,
                                const CrashDiagState& previousDiag, bool previousDiagValid,
                                uint32_t coredumpSize, uint32_t coredumpSeq) {
  if (!crashQueuePoprawna(rtcCrashReportQueue)) {
    memset((void*)&rtcCrashReportQueue, 0, sizeof(rtcCrashReportQueue));
    rtcCrashReportQueue.magic = RTC_CRASH_QUEUE_MAGIC;
  }

  uint8_t idx;
  if (rtcCrashReportQueue.count < 4) {
    idx = (rtcCrashReportQueue.head + rtcCrashReportQueue.count) % 4;
    rtcCrashReportQueue.count++;
  } else {
    // Kolejka pelna: zachowaj 3 starsze + NAJNOWSZY crash.
    rtcCrashReportQueue.head = (rtcCrashReportQueue.head + 1) % 4;
    idx = (rtcCrashReportQueue.head + 3) % 4;
  }

  CrashReportEntry e;
  memset(&e, 0, sizeof(e));
  e.bootCounter = logBootCounter;
  e.resetReason = (uint8_t)reason;
  e.streak = streak;
  e.previousBootCounter = previousDiagValid ? previousDiag.bootCounter : 0;
  e.coredumpSeq = coredumpSeq;
  e.coredumpSize = coredumpSize;
  e.textSent = 0;
  e.fileSent = (coredumpSeq == 0) ? 1 : 0;
  e.previousDiag = previousDiag;
  if (!previousDiagValid) {
    memset(&e.previousDiag, 0, sizeof(e.previousDiag));
  }
  rtcCrashReportQueue.entry[idx] = e;
}

static bool crashReportQueuePusta() {
  return !crashQueuePoprawna(rtcCrashReportQueue) || rtcCrashReportQueue.count == 0;
}

static CrashReportEntry crashReportQueueNajstarszy() {
  CrashReportEntry e;
  memset(&e, 0, sizeof(e));
  if (crashQueuePoprawna(rtcCrashReportQueue) && rtcCrashReportQueue.count > 0) {
    e = rtcCrashReportQueue.entry[rtcCrashReportQueue.head];
  }
  return e;
}

static void crashReportQueueZapiszNajstarszy(const CrashReportEntry& e) {
  if (!crashQueuePoprawna(rtcCrashReportQueue) || rtcCrashReportQueue.count == 0) return;
  rtcCrashReportQueue.entry[rtcCrashReportQueue.head] = e;
}

static void crashReportQueueUsunNajstarszy() {
  if (!crashQueuePoprawna(rtcCrashReportQueue) || rtcCrashReportQueue.count == 0) return;
  rtcCrashReportQueue.head = (rtcCrashReportQueue.head + 1) % 4;
  rtcCrashReportQueue.count--;
}

static String buildTelegramCrashReport(const CrashReportEntry& e) {
  String s;
  s.reserve(1100);
  s += "<b>CRASH / restart centrali</b>\n";
  s += "boot=" + String((unsigned long)e.bootCounter);
  s += " reset=" + String(resetReasonNaTekst((esp_reset_reason_t)e.resetReason));
  s += " streak=" + String((unsigned)e.streak) + "\n";

  if (e.previousBootCounter != 0) {
    s += "poprzedni_boot=" + String((unsigned long)e.previousBootCounter);
    s += " twdt_isr_count=" + String((unsigned long)e.previousDiag.twdtIsrCount) + "\n";
    if (e.previousDiag.twdtIsrCount > 0 ||
        e.previousDiag.twdtCurrentNameCore0[0] != '\0' ||
        e.previousDiag.twdtCurrentNameCore1[0] != '\0') {
      s += "TWDT ISR: cpu0=" + String(e.previousDiag.twdtCurrentNameCore0);
      s += " cpu1=" + String(e.previousDiag.twdtCurrentNameCore1) + "\n";
    }
    s += "<b>Ostatnie checkpointy przed resetem:</b>\n";
    for (uint8_t i = 0; i < 4; i++) {
      const CrashDiagTaskState &t = e.previousDiag.task[i];
      if (t.seq == 0) continue;
      s += String(diagTaskName(i + 1));
      s += " op=" + String(diagOpName(t.op));
      s += " etap=" + String(diagStageName(t.stage));
      s += " detail=" + String((unsigned)t.detail);
      if (t.op == DIAG_OP_SCHEDULER) {
        s += " zadanie=" + String(diagSchedulerName(t.detail));
      }
      s += " up_ms=" + String((unsigned long)t.uptimeMs);
      s += " heap=" + String((unsigned long)t.freeHeap);
      s += " largest=" + String((unsigned long)t.largestBlock);
      s += " stack_hwm=" + String((unsigned long)t.stackHwmWords) + "\n";
    }
  } else {
    s += "brak poprawnego snapshotu poprzedniego boota\n";
  }

  if (e.coredumpSeq > 0 && e.coredumpSize > 0) {
    char nazwa[80];
    snprintf(nazwa, sizeof(nazwa), "dump_seq%010lu_boot%lu.bin",
             (unsigned long)e.coredumpSeq, (unsigned long)e.bootCounter);
    s += "coredump_seq=" + String((unsigned long)e.coredumpSeq);
    s += " plik=" + String(nazwa);
    s += " rozmiar=" + String((unsigned long)e.coredumpSize) + "B\n";
    s += "Plik zostanie wyslany automatycznie po nawiazaniu Telegrama.";
  } else {
    s += "coredump=brak (nie znaleziono / nie zapisano)";
  }
  return s;
}

// Deklaracja sendTelegramMessage() jest juz dostepna wczesniej w pliku.
static unsigned long crashReportLastRetryMs = 0;

static void wyslijZalegleRaportyCrash() {
  if (!tgEnabled || crashReportQueuePusta()) return;

  unsigned long teraz = millis();
  if (crashReportLastRetryMs != 0 && (teraz - crashReportLastRetryMs) < 60000UL) return;
  crashReportLastRetryMs = teraz;

  while (!crashReportQueuePusta()) {
    CrashReportEntry e = crashReportQueueNajstarszy();
    if (e.bootCounter == 0) {
      crashReportQueueUsunNajstarszy();
      continue;
    }

    if (!e.textSent) {
      String tresc = buildTelegramCrashReport(e);
      bool okText = sendTelegramMessage(tresc);
      if (!okText) {
        zapiszLog(String(F("tag=CRASH-TG lvl=WARN zdarzenie=raport_odroczony boot=")) + String((unsigned long)e.bootCounter) +
                  " reset=" + resetReasonNaTekst((esp_reset_reason_t)e.resetReason) +
                  " etap=tekst msg=Telegram_niedostepny_retry_za_ge_60s");
        break;
      }
      e.textSent = 1;
      crashReportQueueZapiszNajstarszy(e);
      zapiszLog(String(F("tag=CRASH-TG lvl=INFO zdarzenie=raport_tekst_wyslany boot=")) + String((unsigned long)e.bootCounter) +
                " reset=" + resetReasonNaTekst((esp_reset_reason_t)e.resetReason));
    }

    if (!e.fileSent && e.coredumpSeq > 0) {
      String sciezka;
      uint32_t bootPliku = 0;
      size_t rozmiarPliku = 0;
      if (!coredumpZnajdzPoSeq(e.coredumpSeq, sciezka, bootPliku, rozmiarPliku)) {
        zapiszLog(String(F("tag=CRASH-TG lvl=WARN zdarzenie=plik_coredump_brak boot=")) + String((unsigned long)e.bootCounter) +
                  " coredump_seq=" + String((unsigned long)e.coredumpSeq) +
                  " msg=pozostawiono_w_kolejce");
        break;
      }

      bool okFile = sendTelegramCoredumpPlik(sciezka, bootPliku, e.coredumpSeq);
      if (!okFile) {
        zapiszLog(String(F("tag=CRASH-TG lvl=WARN zdarzenie=plik_odroczony boot=")) + String((unsigned long)e.bootCounter) +
                  " coredump_seq=" + String((unsigned long)e.coredumpSeq) +
                  " msg=Telegram_niedostepny_lub_wysylka_nieudana_retry_za_ge_60s");
        break;
      }
      e.fileSent = 1;
      crashReportQueueZapiszNajstarszy(e);
      zapiszLog(String(F("tag=CRASH-TG lvl=INFO zdarzenie=plik_wyslany boot=")) + String((unsigned long)e.bootCounter) +
                " coredump_seq=" + String((unsigned long)e.coredumpSeq));
    }

    if (e.textSent && e.fileSent) {
      zapiszLog(String(F("tag=CRASH-TG lvl=INFO zdarzenie=raport_zakonczony boot=")) + String((unsigned long)e.bootCounter) +
                " reset=" + resetReasonNaTekst((esp_reset_reason_t)e.resetReason));
      crashReportQueueUsunNajstarszy();
    } else {
      // Coredump nie istnial dla tego raportu — tekst jest wtedy calym raportem.
      if (e.coredumpSeq == 0) {
        crashReportQueueUsunNajstarszy();
      }
      break;
    }
  }
}

// [POWERON-TG] POWERON nie jest klasyfikowany jako crash przez bylCrash(),
// ale przy uruchomieniu po powrocie zasilania chcemy wyslac osobny alert.
static bool powerOnNoticeStatePoprawny() {
  return rtcPowerOnNotice.magic == RTC_POWERON_NOTICE_MAGIC &&
         rtcPowerOnNotice.pending <= 1 &&
         (!rtcPowerOnNotice.pending ||
          (rtcPowerOnNotice.resetReason == (uint8_t)ESP_RST_POWERON &&
           rtcPowerOnNotice.bootCounter > 0));
}

static void powerOnNoticeZainicjalizuj() {
  if (powerOnNoticeStatePoprawny()) return;
  memset((void*)&rtcPowerOnNotice, 0, sizeof(rtcPowerOnNotice));
  rtcPowerOnNotice.magic = RTC_POWERON_NOTICE_MAGIC;
}

static void powerOnNoticeZaplanuj(esp_reset_reason_t reason) {
  if (reason != ESP_RST_POWERON) return;
  powerOnNoticeZainicjalizuj();
  rtcPowerOnNotice.bootCounter = logBootCounter;
  rtcPowerOnNotice.resetReason = (uint8_t)reason;
  rtcPowerOnNotice.pending = 1;
}

static unsigned long powerOnNoticeLastRetryMs = 0;
static bool powerOnNoticeRetryArmed = false;

static void wyslijZaleglePowiadomieniePowerOn() {
  if (!powerOnNoticeStatePoprawny() || !rtcPowerOnNotice.pending || !tgEnabled) return;

  const unsigned long teraz = millis();
  if (powerOnNoticeRetryArmed && (teraz - powerOnNoticeLastRetryMs) < 60000UL) return;
  powerOnNoticeRetryArmed = true;
  powerOnNoticeLastRetryMs = teraz;

  String tresc;
  tresc.reserve(380);
  tresc += F("<b>POWERON — uruchomienie centrali</b>\n");
  tresc += F("ESP32 zarejestrowal start z przyczyna POWERON (powrot/pojawienie sie zasilania).\n");
  tresc += F("Ten kod nie rozroznia celowego odlaczenia od krotkiej przerwy w zasilaniu.\n");
  tresc += F("To nie jest raport crashu programu. Jesli nikt nie odlaczal zasilania, sprawdz zasilacz i polaczenia.\n");
  tresc += "boot=" + String((unsigned long)rtcPowerOnNotice.bootCounter);
  tresc += " firmware=" + String(FIRMWARE_VERSION);

  if (!sendTelegramMessage(tresc)) {
    zapiszLog(String(F("tag=BOOT-TG lvl=WARN zdarzenie=raport_odroczony boot=")) +
              String((unsigned long)rtcPowerOnNotice.bootCounter) +
              " reset=POWERON etap=tekst retry_za_ge_60s");
    return;
  }

  const uint32_t boot = rtcPowerOnNotice.bootCounter;
  rtcPowerOnNotice.pending = 0;
  zapiszLog(String(F("tag=BOOT-TG lvl=INFO zdarzenie=raport_wyslany boot=")) +
            String((unsigned long)boot) + " reset=POWERON");
}

// ── SCHEDULER — prosty zamiennik leOS2 oparty o millis() ────────────────
struct ZadanieCykliczne {
  void (*funkcja)();
  unsigned long interwalMs;
  unsigned long ostatnieWywolanie;
  bool aktywne;
};
// [FIX MAX_ZADAN, ta sesja] Bylo 16 - dokladnie tyle, ile mieszczcy sie w
// trybie symulacji (TRYB_BEZ_SPRZETU), ale tryb SPRZETOWY rejestruje 17
// zadan (12 bezwarunkowych + cisnienie/wilgotnosc + RTC + zadanieSyncNTP +
// historiaZapiszProbke) - o JEDNO za duzo. dodajZadanie() przy przekroczeniu
// limitu tylko loguje blad i CICHO pomija zadanie (nie crashuje), wiec objaw
// byl subtelny: `historiaZapiszProbke` (rejestrowane jako ostatnie w tej
// galezi) nigdy sie nie wykonywalo, czyli bufor historii (WYKRESY na LCD)
// nigdy nie dostawal nowych probek po starcie - tylko to, co wczytane z
// dysku przy boocie, plasko juz na zawsze. 20 = 17 realnie potrzebnych +3
// zapasu na przyszle dodajZadanie(), zamiast znow zapychac limit "na styk".
const int MAX_ZADAN = 20;
ZadanieCykliczne zadania[MAX_ZADAN];
int liczbaZadan = 0;

void dodajZadanie(void (*funkcja)(), unsigned long interwalMs) {
  if (liczbaZadan >= MAX_ZADAN) {
    DLOG(DC_SCHEDULER, DL_ERR, F("zdarzenie=limit_zadan msg=\"MAX_ZADAN przekroczone, zadanie nie zostalo dodane\""));
    return;
  }
  zadania[liczbaZadan] = {funkcja, interwalMs, 0, true};
  liczbaZadan++;
}
void wstrzymajZadanie(void (*funkcja)()) {
  for (int i = 0; i < liczbaZadan; i++) if (zadania[i].funkcja == funkcja) zadania[i].aktywne = false;
}
void wznowZadanie(void (*funkcja)()) {
  for (int i = 0; i < liczbaZadan; i++) if (zadania[i].funkcja == funkcja) zadania[i].aktywne = true;
}

// [RESET-DIAG] Nazwa slotu schedulera do raportu Telegram. Numery sa celowo
// zgodne 1:1 z kolejnoscia dodajZadanie() w setup(); dzieki temu raport z
// poprzedniego boota nie wymaga otwierania kodu tylko po to, by odgadnac slot.
static const char* diagSchedulerName(uint16_t i) {
  switch (i) {
    case 0:  return "zadanieObslugaPompy";
    case 1:  return "servo_manual";
    case 2:  return "obslugaRozpalaniaSerwa";
    case 3:  return "serwoTick";
    case 4:  return "Czujnik_DS";
    case 5:  return "dsObslugaPowerCycle";
    case 6:  return "pozar";
    case 7:  return "buzzerAlarmuCentrali";
    case 8:  return "mieszadlo";
    case 9:  return "obslugaWygasanSymulacjiElementow";
    case 10: return "temperatura_alarmowa";
    case 11: return "obliczanie_srednia";
    case 12: return "zadanieStatusSerial";
#ifndef TRYB_BEZ_SPRZETU
    case 13: return "cisnienie";
    case 14: return "wilgotnosc";
    case 15: return "RTC";
    case 16: return "zadanieSyncNTP";
    case 17: return "historiaZapiszProbke";
#else
    case 13: return "RTC";
    case 14: return "zadanieSyncNTP";
    case 15: return "historiaZapiszProbke";
    case 16: return "aktualizujScenariuszTestowy";
#endif
    default: return "?";
  }
}

void wykonajZaplanowaneZadania() {
  unsigned long teraz = millis();
  for (int i = 0; i < liczbaZadan; i++) {
    if (zadania[i].aktywne && (teraz - zadania[i].ostatnieWywolanie >= zadania[i].interwalMs)) {
      zadania[i].ostatnieWywolanie = teraz;
      // [RESET-DIAG] Jesli funkcja schedulera zawiesi loopTask/IWDT, po restarcie
      // bedzie wiadomo, KTORY numer zadania byl wykonywany.
      diagCheckpoint(DIAG_TASK_LOOP, DIAG_OP_SCHEDULER, DIAG_STAGE_BEFORE, (uint16_t)i);
      zadania[i].funkcja();
      diagCheckpoint(DIAG_TASK_LOOP, DIAG_OP_SCHEDULER, DIAG_STAGE_AFTER, (uint16_t)i);
    }
  }
}

