// Wybor wzoru brzeczyka wspoldzielony z aplikacja Android i zapisywany w NVS.
// Klucze sa krotkie (<=15 znakow), a dostep miedzy tgTask/JSON i zadaniem
// buzzera chroni krotka sekcja krytyczna bez alokacji pamieci.
static portMUX_TYPE alarmSoundConfigMux = portMUX_INITIALIZER_UNLOCKED;
static uint8_t alarmSoundDymId = static_cast<uint8_t>(AlarmBuzzerProfiles::SoundId::Siren);
static uint8_t alarmSoundOgrzId = static_cast<uint8_t>(AlarmBuzzerProfiles::SoundId::Bell);
static uint8_t alarmSoundBothId = static_cast<uint8_t>(AlarmBuzzerProfiles::SoundId::TwoTone);
static bool alarmBuzzerResetRequested = false;

// Jeden, nieblokujacy odtwarzacz obsluguje pojedynczy fizyczny brzeczyk.
// faza=0 oznacza zatrzymany; faza 1..N to aktywny krok wzoru.
byte fazaAlarmuDzwiekowego = 0;
unsigned long czasFazyAlarmuDzwiekowego = 0;
static uint8_t alarmBuzzerPlayingSoundId = 0xFF;
static uint8_t alarmBuzzerPlayingKind = 0xFF;

static uint8_t alarmSoundReadId(AlarmBuzzerProfiles::AlarmKind kind) {
  uint8_t value;
  portENTER_CRITICAL(&alarmSoundConfigMux);
  switch (kind) {
    case AlarmBuzzerProfiles::AlarmKind::Heat: value = alarmSoundOgrzId; break;
    case AlarmBuzzerProfiles::AlarmKind::Both: value = alarmSoundBothId; break;
    case AlarmBuzzerProfiles::AlarmKind::Smoke:
    default: value = alarmSoundDymId; break;
  }
  portEXIT_CRITICAL(&alarmSoundConfigMux);
  return AlarmBuzzerProfiles::isValidSound(value)
      ? value
      : static_cast<uint8_t>(AlarmBuzzerProfiles::defaultSound(kind));
}

static void alarmSoundReadSnapshot(uint8_t& dym, uint8_t& ogrz, uint8_t& both) {
  portENTER_CRITICAL(&alarmSoundConfigMux);
  dym = alarmSoundDymId;
  ogrz = alarmSoundOgrzId;
  both = alarmSoundBothId;
  portEXIT_CRITICAL(&alarmSoundConfigMux);
  if (!AlarmBuzzerProfiles::isValidSound(dym)) dym = static_cast<uint8_t>(AlarmBuzzerProfiles::SoundId::Siren);
  if (!AlarmBuzzerProfiles::isValidSound(ogrz)) ogrz = static_cast<uint8_t>(AlarmBuzzerProfiles::SoundId::Bell);
  if (!AlarmBuzzerProfiles::isValidSound(both)) both = static_cast<uint8_t>(AlarmBuzzerProfiles::SoundId::TwoTone);
}

static void alarmSoundWriteId(AlarmBuzzerProfiles::AlarmKind kind, uint8_t value) {
  if (!AlarmBuzzerProfiles::isValidSound(value)) return;
  portENTER_CRITICAL(&alarmSoundConfigMux);
  switch (kind) {
    case AlarmBuzzerProfiles::AlarmKind::Heat: alarmSoundOgrzId = value; break;
    case AlarmBuzzerProfiles::AlarmKind::Both: alarmSoundBothId = value; break;
    case AlarmBuzzerProfiles::AlarmKind::Smoke:
    default: alarmSoundDymId = value; break;
  }
  alarmBuzzerResetRequested = true;
  portEXIT_CRITICAL(&alarmSoundConfigMux);
}

static void alarmBuzzerRequestReset() {
  portENTER_CRITICAL(&alarmSoundConfigMux);
  alarmBuzzerResetRequested = true;
  portEXIT_CRITICAL(&alarmSoundConfigMux);
}

static bool alarmBuzzerTakeResetRequest() {
  portENTER_CRITICAL(&alarmSoundConfigMux);
  const bool requested = alarmBuzzerResetRequested;
  alarmBuzzerResetRequested = false;
  portEXIT_CRITICAL(&alarmSoundConfigMux);
  return requested;
}

static void alarmBuzzerStopHardware() {
  noTone(pinBuzer);
  digitalWrite(pinZasilanieBuzera, LOW);
  fazaAlarmuDzwiekowego = 0;
  alarmBuzzerPlayingSoundId = 0xFF;
  alarmBuzzerPlayingKind = 0xFF;
}


