// [PLAN_HISTORIA_I_USTAWIENIA_TELEGRAM.md, Czesc 7] Wysylka log_ustawien.txt
// jako dokument Telegram. W odroznieniu od HistKrotka/HistDluga powyzej,
// ten plik MA cache rozmiaru (g_logUstawienSize) - moze byc pisany z innego
// kontekstu (panel WWW / komenda Firebase, przez ustawParametrPieca()) niz
// ten, ktory go wysyla, tym samym wzorcem co g_logKrytycznySize. Plik po
// wdrozeniu Czesci 3 zawsze ma co najmniej linie BASELINE, wiec
// totalLogSize==0 oznacza realny blad (plik jeszcze nie istnieje / LittleFS
// padl), nie stan prawidlowy.
bool sendTelegramDocumentUstawien() {
  if (!tgEnabled || tgBotToken.length() < 10 || tgChatId.length() < 3) return false;
  if (WiFi.status() != WL_CONNECTED) return false;
  if (!littlefsReady) return false;
  if (!LittleFS.exists(LOG_USTAWIEN_PLIK)) return false;

  size_t totalLogSize = g_logUstawienSize;
  if (totalLogSize == 0) return false;

  const size_t MAX_TG_DOC_UST = 45UL * 1024UL * 1024UL;

  if (!tgWezmijSendMutex("TG-DOC-UST")) return false;

  bool ok = false;
  bool tgDocNetFailCounted = false;
  auto tgDocNetFail = [&]() {
    if (!tgDocNetFailCounted) { TG_NET_FAIL(); tgDocNetFailCounted = true; }
  };

  tgClient.stop();
  tgClientReady = false;

  if (tgEnsureConnected(tgClient, tgClientReady, tgClientLastUse)) {
    size_t sendSize = (totalLogSize > MAX_TG_DOC_UST) ? MAX_TG_DOC_UST : totalLogSize;
    const String boundary = "ESP32TGBndUst1";
    String caption = "Dziennik nastaw (" + String((unsigned)(sendSize / 1024)) + " KB)";

    String partHead =
      "--" + boundary + "\r\n"
      "Content-Disposition: form-data; name=\"chat_id\"\r\n\r\n" +
      tgChatId + "\r\n"
      "--" + boundary + "\r\n"
      "Content-Disposition: form-data; name=\"caption\"\r\n\r\n" +
      caption + "\r\n"
      "--" + boundary + "\r\n"
      "Content-Disposition: form-data; name=\"document\"; filename=\"log_ustawien.txt\"\r\n"
      "Content-Type: text/plain\r\n\r\n";
    String partTail = "\r\n--" + boundary + "--\r\n";
    size_t totalLen = partHead.length() + sendSize + partTail.length();

    serwisujTWDTJesliZarejestrowany();
    if (!tgWriteGuard(tgClient)) { tgDocNetFail(); goto tgDocUstSendDone; }
    tgClient.print(String("POST /bot") + tgBotToken + "/sendDocument HTTP/1.1\r\n" +
                   "Host: " + TG_HOST + "\r\n" +
                   "Content-Type: multipart/form-data; boundary=" + boundary + "\r\n" +
                   "Content-Length: " + String((unsigned)totalLen) + "\r\n" +
                   "Connection: close\r\n\r\n");
    serwisujTWDTJesliZarejestrowany();
    if (!tgWriteGuard(tgClient)) { tgDocNetFail(); goto tgDocUstSendDone; }
    tgClient.print(partHead);

    {
      const size_t DOC_CHUNK = 4096;
      uint8_t* chBuf = (uint8_t*) ps_malloc(DOC_CHUNK);
      if (!chBuf) chBuf = (uint8_t*) malloc(DOC_CHUNK);

      if (!chBuf) {
        DLOG(DC_TELEGRAM, DL_ERR, F("TG-DOC-UST msg=\"brak pamieci na bufor 4KB\""));
      } else {
        File plik = LittleFS.open(LOG_USTAWIEN_PLIK, "r");
        if (plik) {
          size_t wyslano = 0;
          while (wyslano < sendSize) {
            size_t doOdczytu = (sendSize - wyslano > DOC_CHUNK) ? DOC_CHUNK : (sendSize - wyslano);
            size_t n = plik.read(chBuf, doOdczytu);
            if (n == 0) break;
            if (!tgWriteGuard(tgClient)) { tgDocNetFail(); break; }
            size_t zapisano = 0;
            while (zapisano < n) {
              size_t w = tgClient.write(chBuf + zapisano, n - zapisano);
              if (w == 0) break;
              zapisano += w;
            }
            if (zapisano == 0) break;
            wyslano += zapisano;
            serwisujTWDTJesliZarejestrowany();
          }
          plik.close();
        }
        free(chBuf);
      }
    }

    serwisujTWDTJesliZarejestrowany();
    if (!tgWriteGuard(tgClient)) { tgDocNetFail(); goto tgDocUstSendDone; }
    tgClient.print(partTail);

    {
      String response;
      response.reserve(768);
      unsigned long readStart = millis();
      while ((tgClient.connected() || tgClient.available()) && millis() - readStart < 12000UL) {
        while (tgClient.available()) {
          char c = (char) tgClient.read();
          if (response.length() < 700) response += c;
          serwisujTWDTJesliZarejestrowany();
        }
        if (!tgClient.connected() && !tgClient.available()) break;
        serwisujTWDTJesliZarejestrowany();
        delay(5);
      }
      ok = response.indexOf("\"ok\":true") >= 0;
      Serial.printf("tag=TG-DOC-UST zdarzenie=odpowiedz tresc=%s\n",
        response.length() > 0 ? response.c_str() : "(pusta)");
    }
  }

  tgDocUstSendDone:
  tgClient.stop();
  tgClientReady = false;
  xSemaphoreGive(tgSendMutex);
  return ok;
}

// [PLAN_SD_LOGI_AWARYJNE.md, Czesc 6.2] Sprobuj wyslac zalegle archiwum SD,
// gdy siec/Telegram sa dostepne. Warunki identyczne jak przy kazdej innej
// automatycznej wysylce Telegrama w tym pliku (tgEnabled, WiFi, circuit
// breaker) + Czesc 6.1 (jest w ogole co wysylac). Jeszcze NIE wolana z
// zadnej petli - podpiecie to Czesc 6.3.
void tgAutoWyslijZaleglySD() {
  if (!tgEnabled) return;
  if (WiFi.status() != WL_CONNECTED) return;
  if (tgNetCircuitOpen) return;              // ten sam circuit breaker co reszta Telegrama
  if (!sdArchiwumCzekaNaWyslanie()) return;   // Czesc 6.1 — nic do wyslania, szybki wyjscie

  serwisujTWDTJesliZarejestrowany();  // sendTelegramDocumentSD() moze potrwac (streaming przez TLS)
  if (sendTelegramDocumentSD()) {
    // Decyzja: auto-wysylka KASUJE archiwum po sukcesie. Inaczej kolejny
    // interwal (Czesc 6.3) wyslalby to samo archiwum ponownie w kolko, w
    // nieskonczonosc. To CELOWO inne zachowanie niz reczny przycisk
    // "Pobierz logi z SD" (Czesc 5), ktory NIE kasuje — tam zalozenie bylo
    // "podglad na zadanie", tutaj celem jest "wyczyscic zaleglosc raz a
    // porzadnie", wiec kasowanie ma sens.
    if (sdDostepna && SD.exists(SD_LOG_ARCHIWUM_PLIK)) SD.remove(SD_LOG_ARCHIWUM_PLIK);
    DLOG(DC_LOGI, DL_INFO, F("LOGI-SD zdarzenie=auto_wyslano_sd msg=\"archiwum SD wyslane automatycznie po powrocie sieci, skasowane\""));
  } else {
    DLOG(DC_LOGI, DL_WARN, F("LOGI-SD zdarzenie=auto_wysylka_sd_nieudana msg=\"sprobuje ponownie przy nastepnej okazji\""));
    // brak kasowania — archiwum zostaje, kolejna proba przy nastepnym
    // wywolaniu (Czesc 6.3 ustala interwal)
  }
}

// --- TELEGRAM - tekstowy opis trybu serwa (1=Auto,2=Reczny,3=Bezpieczna) ---
String trybSerwaTekst(byte t) {
  if (t == 1) return F("AUTO");
  if (t == 2) return F("RECZNY");
  if (t == 3) return F("BEZPIECZNA POZYCJA");
  return F("?");
}

// --- TELEGRAM - zbuduj raport /status z biezacych danych sterownika ---
String buildTelegramStatusReport() {
  String s;
  s.reserve(700);
  s += F("🔥 <b>STEROWNIK KOTŁA C.O. — RAPORT</b>\n");
  s += F("━━━━━━━━━━━━━━━━━━━━\n");
  s += F("🌡️ <b>TEMPERATURY:</b>\n");
  s += F(" • 🔥 Kocioł C.O.: <b>"); s += String(temperaturaOgrzewania, 1); s += F("°C</b> (śr: "); s += String(temperaturaOgrzewaniaSrednia, 1); s += F("°C)\n");
  s += F(" • 💧 Bojler CWU: <b>"); s += String(temperaturaBojlera, 1); s += F("°C</b>\n");
  s += F(" • ☀️ Panel solarny: <b>"); s += String(temperaturaPaneluSlonecznego, 1); s += F("°C</b>\n");
  s += F(" • 🌲 Trociny: <b>"); s += String(temperaturaOgrzewania_Trociny, 1); s += F("°C</b> | 🔄 Powrót: <b>"); s += String(temperaturaOgrzewania_Powrot, 1); s += F("°C</b>\n");
  s += F(" • 🏠 Pokój: <b>"); s += String(temperaturaPomieszczenia, 1); s += F("°C</b> | ❄️ Zewnątrz: <b>"); s += String(temperaturaNaZewnatrz, 1); s += F("°C</b>\n\n");

  s += F("⚙️ <b>STEROWANIE & PRACA:</b>\n");
  s += F(" • 🚰 Pompa C.O.: ");
  if (pompaJestWlaczona()) s += F("<b>🟢 PRACA</b>");
  else s += F("<b>⚪ STOP</b>");
  s += (Wybor == 1) ? F(" (Trociniak)") : F(" (Kopciuch)");
  s += F("\n • 📐 Serwa: Klapa <b>"); s += String(pozycjaKlapa); s += F("°</b> | Syberek <b>"); s += String(pozycjaSyberek); s += F("°</b>\n");
  s += F(" • 🎛️ Tryb serw: <b>"); s += trybSerwaTekst(TrybSerwa); s += F("</b>\n");
  if (czujnikDymuWlaczonyTemperaturowo || czyAlarmAktywny) {
    s += F(" • 🌪️ Dym ADC: <b>"); s += String(czujnikDymuOdczyt); s += F("</b>\n");
  }

  s += F("\n🚨 <b>STATUS BEZPIECZEŃSTWA:</b>\n");
  if (alarmOgrzewanieWlaczone || alarmPanelWlaczone || czyAlarmAktywny) {
    if (alarmOgrzewanieWlaczone) s += F(" • 🚨 <b>ALARM PRZEGRZANIA KOTŁA!</b>\n");
    if (alarmPanelWlaczone)      s += F(" • 🚨 <b>ALARM PRZEGRZANIA PANELU!</b>\n");
    if (czyAlarmAktywny)         s += F(" • 🚨 <b>ALARM ZADYMIENIA!</b>\n");
  } else {
    s += F(" • ✅ <b>Wszystko w normie (brak alarmów)</b>\n");
  }

  s += F("\n📡 <b>SYSTEM & ŁĄCZNOŚĆ:</b>\n");
  s += F(" • 📶 Wi-Fi: <b>");
  if (WiFi.status() == WL_CONNECTED) {
    s += WiFi.SSID();
    s += F("</b> ("); s += String(WiFi.RSSI()); s += F(" dBm)\n • 🌐 IP: <code>"); s += WiFi.localIP().toString(); s += F("</code>\n");
  } else {
    s += F("Brak połączenia</b>\n");
  }
  unsigned long upS = millis() / 1000UL;
  unsigned long upD = upS / 86400UL; upS %= 86400UL;
  unsigned long upH = upS / 3600UL; upS %= 3600UL;
  unsigned long upM = upS / 60UL;
  s += F(" • ⏱️ Uptime: ");
  if (upD > 0) { s += String(upD); s += F("d "); }
  s += String(upH); s += F("h "); s += String(upM); s += F("m\n");
  s += F(" • 📦 Wersja: <b>v"); s += String(FIRMWARE_VERSION); s += F("</b>");

  return s;
}

