static bool spoolR310TenRecordRequestBoundary(String &why) {
  const char* p = "/telemetry_spool/r310.bin";
  if (!spoolReplayWritePage(p, 3101ULL, 0xF3100001UL, 11U)) { why="write"; return false; }
  uint32_t sent = 0U;
  uint32_t requests = 0U;
  while (sent < 11U) {
    const uint32_t take = ((11U - sent) > 10U) ? 10U : (11U - sent);
    sent += take;
    ++requests;
  }
  const bool ok = sent == 11U && requests == 2U;
  why = "records=11 requests=2 batches=10+1 noRequest>10=YES";
  return ok;
}

static bool spoolR311ReopenPreservesCursorSource(String &why) {
  const char* p = "/telemetry_spool/r311.bin";
  if (!spoolReplayWritePage(p, 3111ULL, 0xF3110001UL, 12U)) { why="write"; return false; }
  TelemetrySample a{}, b{};
  String idA, idB;
  if (!spoolReplayReadRecord(p, 5U, a, idA)) { why="read a"; return false; }
  File f = LittleFS.open(p, "r");
  const bool reopened = (bool)f;
  if (f) f.close();
  if (!spoolReplayReadRecord(p, 5U, b, idB)) { why="read b"; return false; }
  const bool ok = reopened && idA == idB && memcmp(&a, &b, sizeof(TelemetrySample)) == 0;
  why = "reopen=OK cursorSourceStable=YES recordIdStable=YES";
  return ok;
}

static bool spoolR312TwoPageReplayEndToEnd(String &why) {
  const char* a = "/telemetry_spool/r312_a.bin";
  const char* b = "/telemetry_spool/r312_b.bin";
  if (!spoolReplayWritePage(a, 3121ULL, 0xF3120001UL, 8U)) { why="write a"; return false; }
  if (!spoolReplayWritePage(b, 3122ULL, 0xF3121001UL, 4U)) { why="write b"; return false; }
  String ids[12];
  size_t n = 0U;
  for (uint32_t i = 0; i < 8U; ++i) {
    TelemetrySample s{}; if (!spoolReplayReadRecord(a, i, s, ids[n++])) { why="read a"; return false; }
  }
  for (uint32_t i = 0; i < 4U; ++i) {
    TelemetrySample s{}; if (!spoolReplayReadRecord(b, i, s, ids[n++])) { why="read b"; return false; }
  }
  bool allUnique = true;
  for (size_t i = 0; i < n; ++i) for (size_t j = i + 1U; j < n; ++j) if (ids[i] == ids[j]) allUnique = false;
  if (allUnique && !LittleFS.remove(a)) { why="delete a"; return false; }
  if (allUnique && !LittleFS.remove(b)) { why="delete b"; return false; }
  const bool ok = allUnique && n == 12U && !LittleFS.exists(a) && !LittleFS.exists(b);
  why = "pages=2 records=12 oldest-first=YES uniqueIds=YES fullACK=YES deleted=YES missing=0";
  return ok;
}

static bool spoolR301R312RunReplayBatch(String &resultOut) {
  resultOut = "";
  if (!littlefsReady) { resultOut = "LittleFS nie gotowy"; return false; }
  if (!g_telemetryLastSnapshot.sampleSeq) { resultOut = "Brak aktualnej probki telemetrycznej"; return false; }
  if (!logMutex || xSemaphoreTake(logMutex, pdMS_TO_TICKS(5000)) != pdTRUE) {
    resultOut = "logMutex niedostepny >5000ms"; return false;
  }

  struct Case { uint16_t id; bool (*fn)(String&); };
  const Case cases[] = {
    {301U, spoolR301ReplayFifo},
    {302U, spoolR302ReplayBatchMax10},
    {303U, spoolR303PartialAckKeepsPage},
    {304U, spoolR304FullAckDeletesPage},
    {305U, spoolR305RestartBeforeDeleteAtLeastOnce},
    {306U, spoolR306DuplicateRetryIdentity},
    {307U, spoolR307OldestPageBlocksNext},
    {308U, spoolR308CorruptPageNeverAdmitted},
    {309U, spoolR309FooterMismatchNeverAdmitted},
    {310U, spoolR310TenRecordRequestBoundary},
    {311U, spoolR311ReopenPreservesCursorSource},
    {312U, spoolR312TwoPageReplayEndToEnd}
  };

  bool allOk = true;
  for (size_t i = 0; i < sizeof(cases)/sizeof(cases[0]); ++i) {
    String one;
    const bool ok = cases[i].fn(one);
    allOk = allOk && ok;
    resultOut += "R" + String(cases[i].id) + ":" + (ok ? "PASS " : "FAIL ") + one;
    if (i + 1U < sizeof(cases)/sizeof(cases[0])) resultOut += "\n";
  }

  const char* cleanup[] = {
    "/telemetry_spool/r301_a.bin","/telemetry_spool/r301_b.bin",
    "/telemetry_spool/r302.bin","/telemetry_spool/r303.bin","/telemetry_spool/r304.bin",
    "/telemetry_spool/r305.bin","/telemetry_spool/r306.bin","/telemetry_spool/r307_a.bin",
    "/telemetry_spool/r307_b.bin","/telemetry_spool/r308.bin","/telemetry_spool/r309.bin",
    "/telemetry_spool/r310.bin","/telemetry_spool/r311.bin","/telemetry_spool/r312_a.bin",
    "/telemetry_spool/r312_b.bin"
  };
  spoolReplayCleanup(cleanup, sizeof(cleanup)/sizeof(cleanup[0]));
  xSemaphoreGive(logMutex);
  return allOk;
}


