static bool spoolR324TwoPageQuota(String &why) {
  const size_t twoPages = 2U * 64640U;
  FsQuotaHard q{};
  if (!fsQuotaHardEvaluate(q)) {
    why = "quotaEvaluate=FAIL";
    return false;
  }

  // R324 nie może zakładać, że bieżące quota kończy się dokładnie na 2 stronach:
  // to jest stan zależny od aktualnego użycia LittleFS. Testujemy więc dwie rzeczy
  // na jednym spójnym snapshotcie:
  //   1) wielostronicowy backlog 2 x 64640 B jest dopuszczalny,
  //   2) sama granica hard quota działa: exact=ADMIT, quota+1=REJECT.
  const bool twoPagesAdmitted = q.ok && twoPages <= q.availableQuotaBytes;

  size_t exactFree = 0, exactProtected = 0, exactQuota = 0;
  const bool exactAdmitted =
      fsQuotaTelemetryAdmission(q.availableQuotaBytes, exactFree, exactProtected, exactQuota);

  const size_t overQuota = q.availableQuotaBytes + 1U;
  size_t overFree = 0, overProtected = 0, overQuotaSnapshot = 0;
  const bool overQuotaAdmitted =
      fsQuotaTelemetryAdmission(overQuota, overFree, overProtected, overQuotaSnapshot);

  const bool sameSnapshot =
      exactQuota == q.availableQuotaBytes && overQuotaSnapshot == q.availableQuotaBytes &&
      exactProtected == q.protectedReserveBytes && overProtected == q.protectedReserveBytes;
  const bool protectedPreserved = q.freeBytes >= q.protectedReserveBytes;
  const bool ok = twoPagesAdmitted && exactAdmitted && !overQuotaAdmitted && sameSnapshot && protectedPreserved;

  why = "twoPages=" + String((unsigned long)twoPages) +
        " twoPagesAdmission=" + (twoPagesAdmitted ? "ADMIT" : "REJECT") +
        " free=" + String((unsigned long)q.freeBytes) +
        " protected=" + String((unsigned long)q.protectedReserveBytes) +
        " quota=" + String((unsigned long)q.availableQuotaBytes) +
        " exactQuota=" + (exactAdmitted ? "ADMIT" : "REJECT") +
        " overQuota=" + (overQuotaAdmitted ? "ADMIT" : "REJECT") +
        " snapshotStable=" + (sameSnapshot ? "YES" : "NO") +
        " protectedPreserved=" + (protectedPreserved ? "YES" : "NO");
  return ok;
}

