static bool spoolR269BadPartNoPublish(String &why) {
  const char* dest="/telemetry_spool/r_batch_269.bin"; const char* part="/telemetry_spool/r_batch_269.bin.part";
  if(!spoolBatchWriteCommittedPage(dest,2690ULL,0xF2690001UL,1U,false,false,false,false)){why="dest write";return false;}
  if(!spoolBatchWriteCommittedPage(part,2691ULL,0xF2691001UL,1U,false,false,false,false)){why="part write";return false;}
  // Celowo psujemy footer commit w .part, zachowujac plik finalny nietkniety.
  File f=LittleFS.open(part,"r"); if(!f){why="part open";return false;} const size_t sz=f.size(); uint8_t* buf=(uint8_t*)malloc(sz); if(!buf){f.close();why="malloc";return false;}
  const size_t got=f.read(buf,sz); f.close(); if(got!=sz){free(buf);why="read";return false;}
  SpoolPageFooter* ft=reinterpret_cast<SpoolPageFooter*>(buf+sz-SPOOL_FOOTER_BYTES); ft->commitMarker^=1U; ft->footerCrc32=spoolR245FooterCrc(*ft);
  if(!LittleFS.remove(part)){free(buf);why="remove part";return false;} f=LittleFS.open(part,"w"); if(!f){free(buf);why="rewrite part";return false;}
  const bool ww=f.write(buf,sz)==sz; f.flush(); f.close(); free(buf); if(!ww){why="rewrite";return false;}
  SpoolBatchScan bad; if(!spoolBatchScan(part,bad)||bad.footerOk){why="bad part accepted";return false;}
  SpoolBatchScan before; if(!spoolBatchScan(dest,before)||!before.footerOk||before.pageSeq!=2690ULL){why="dest before bad";return false;}
  // Simulacja gate: nie publikujemy, skoro verify .part nie przeszlo.
  SpoolBatchScan after; if(!spoolBatchScan(dest,after)||!after.footerOk||after.pageSeq!=2690ULL||LittleFS.exists(part)==false){why="dest changed or part vanished";return false;}
  why="bad .part rejected; final pageSeq=2690 preserved"; return true;
}

