  uint8_t rec[SPOOL_RECORD_BYTES]={}; memcpy(rec,&src,sizeof(src)); uint32_t crc=spoolR245Crc32(rec,sizeof(src)); memcpy(rec+sizeof(src),&crc,4);
  File f=LittleFS.open(path,"w"); if(!f){why="open";return false;} bool ok=f.write(rec,sizeof(rec))==sizeof(rec); f.flush(); f.close(); if(!ok){why="write";return false;}
  f=LittleFS.open(path,"r"); if(!f){why="reopen";return false;} uint8_t back[SPOOL_RECORD_BYTES]={}; bool rd=f.read(back,sizeof(back))==sizeof(back); f.close(); if(!rd){why="read";return false;}
  TelemetrySample dst{}; memcpy(&dst,back,sizeof(dst)); uint32_t backCrc=0; memcpy(&backCrc,back+sizeof(dst),4);
