// --- TELEGRAM - potwierdzenie czyszczenia logow (przycisk "Wyczysc logi") ---
// [CZESC 3, B3 wariant z potwierdzeniem] Wzorem sendTelegramConfirmClear()
// z Ryb — dwa przyciski TAK/NIE, faktyczne kasowanie dopiero po kliknieciu
// TAK (TG_CLR_LOGS_DO), NIE jest obslugiwane od razu w pollTelegramCommands()
// (patrz tam), bez przechodzenia przez kolejke.
bool sendTelegramConfirmClearLogs() {
  // [v2.8.1] Bylo: logRozmiarUzyty() — wypelnienie bufora PSRAM (limit
  // LOG_BUF_SIZE=65536UL), niezwiazane z tym, co faktycznie kasuje ta
  // operacja. Tekst ponizej mowi o log_a.txt+log_b.txt (LittleFS), wiec
  // liczba musi pochodzic z logFsRozmiarUzyty() — ta sama funkcja, ktorej
  // juz poprawnie uzywaja pole fsUsed w statusie JSON i odpowiedz na /logi.
  size_t rozmiar = logFsRozmiarUzyty();
  String txt;
  txt += F("<b>Wyczyscic logi?</b>\nAktualny rozmiar bufora: ");
  txt += String((unsigned)rozmiar);
  txt += F(" B\nOperacja jest nieodwracalna (log_a.txt + log_b.txt).");

  String kb;
  kb += F("{\"inline_keyboard\":[[");
  kb += F("{\"text\":\"TAK - wyczysc\",\"callback_data\":\"clr_logs_yes\"},");
  kb += F("{\"text\":\"NIE - anuluj\",\"callback_data\":\"clr_logs_no\"}");
  kb += F("]]}");

  return sendTelegramMessage(txt, kb);
}

// --- TELEGRAM - potwierdzenie restartu ESP32 (przycisk "Restart ESP") ---
// [CZESC 3, B3 wariant z potwierdzeniem] Wzorem sendTelegramConfirmRestart()
// z Ryb — analogicznie do potwierdzenia czyszczenia logow wyzej.
bool sendTelegramConfirmRestart() {
  String kb;
  kb += F("{\"inline_keyboard\":[[");
  kb += F("{\"text\":\"TAK - restartuj\",\"callback_data\":\"restart_yes\"},");
  kb += F("{\"text\":\"NIE - anuluj\",\"callback_data\":\"restart_no\"}");
  kb += F("]]}");

  return sendTelegramMessage(F("<b>Zrestartowac ESP32?</b>\nSterownik bedzie niedostepny przez ok. 10-15s. Piec/pompa/serwa wracaja do normalnej pracy automatycznie po restarcie."), kb);
}

// --- TELEGRAM - odpowiedz na callback_query (wymagane przez Bot API) ---
// [CZESC 3] Bez tego Telegram pokazuje na klikniety przycisk "zegarek" az do
// wewnetrznego timeoutu klienta. Jedyna funkcja w tym module, ktora sama
// zarzadza tgSendMutex/tgPostJson() bezposrednio — nie tworzy zadnej
// wiadomosci widocznej w czacie (inaczej niz sendTelegramMessage()), wiec
// nie pasuje do tamtego wzorca.
void answerTelegramCallback(const String& callbackId) {
  if (!tgEnabled || callbackId.length() == 0) return;
  if (!tgWezmijSendMutex("TG-CB")) return;
  String json = F("{\"callback_query_id\":\"");
  json += callbackId;
  json += F("\"}");
  tgPostJson("/bot" + tgBotToken + "/answerCallbackQuery", json);
  xSemaphoreGive(tgSendMutex);
}

// --- OTA GitHub: adresy budowane raz z GITHUB_OWNER/GITHUB_REPO ---
// api.github.com/.../releases/latest -> JSON z polem "tag_name" (do porownania
// z FIRMWARE_VERSION, bez pobierania binarki).
// github.com/.../releases/latest/download/firmware.bin -> ZAWSZE przekierowuje
// (302) na aktualny adres pliku w releases.githubusercontent.com — ten sam,
// stabilny adres uzyty juz wczesniej przy zakladaniu Release'a w przegladarce.
// [SYNC-OTA/11.4, ta sesja — OTA_PANEL_CALOSC.md] ZMIANA: /releases/latest
// (API) i /releases/latest/download/... (skrot pobierania) POTWIERDZONE
// zrodlowo (docs.github.com), ze CICHO pomijaja prerelease/draft — zero
// bledu, po prostu zwracaja poprzedni prawdziwy Release. Przy nieuwierzytelnionym
// zapytaniu (jak tutaj — brak Authorization) draft i tak jest niewidoczny
// dla nikogo bez push access, wiec realne ryzyko dotyczy WYLACZNIE
// prerelease. Zamiast /releases/latest, /releases?per_page=1 zwraca
// NAJNOWSZY wpis (posortowany po created_at, malejaco) niezaleznie od
// jego flag prerelease/draft — a skoro to string search
// (indexOf("\"tag_name\":\"")), nie ArduinoJson, opakowanie odpowiedzi w
// [ ... ] (tablica zamiast pojedynczego obiektu) nie wymaga zadnej zmiany
// w parsowaniu ponizej.
String otaGithubApiUrl() {
  return "https://api.github.com/repos/" + String(GITHUB_OWNER) + "/" + String(GITHUB_REPO) + "/releases?per_page=1";
}
// [SYNC-OTA/11.4, ta sesja] ZMIANA: zamiast /releases/latest/download/...
// (ktore ma DOKLADNIE ten sam problem z prerelease co API wyzej — to
// tylko redirect do tej samej logiki resolvowania "latest"), adresujemy
// WPROST po znanym tagu: /releases/download/{tag}/{plik} — permalink
// GitHuba, ktory NIE resolwuje "latest" w ogole, wiec nie ma czego
// pominac. Wymaga podania taga (parametr), ktory wywolujacy i tak juz ma
// w rece — to ZAWSZE ten sam tag, ktory chwile wczesniej zwrocil
// sprawdzNajnowszaWersjeGithub(). Dla dzisiejszego, zwyklego (nie-prerelease)
// workflow zachowanie jest bit-identyczne z poprzednim — ten sam plik pod
// tym samym, stabilnym adresem koncowym (permalink, nie redirect
// warunkowy). Zmiana widoczna wylacznie dla przypadku, ktory dzis byl po
// cichu zle obslugiwany.
String otaGithubDownloadUrl(const String &tag) {
  return "https://github.com/" + String(GITHUB_OWNER) + "/" + String(GITHUB_REPO) + "/releases/download/" + tag + "/firmware.bin";
}

// --- OTA GitHub - sprawdz tag najnowszego Release (BEZ pobierania .bin) ---
// UWAGA: api.github.com WYMAGA naglowka User-Agent (brak = 403 Forbidden,
// udokumentowane zachowanie GitHub REST API) — stad recznie ustawiony
// setUserAgent() ponizej.
bool sprawdzNajnowszaWersjeGithub(String &tagOut, String &bladOut) {
  WiFiClientSecure client;
  client.setInsecure();     // jak tgClient — bez weryfikacji certyfikatu (patrz komentarz przy #include WiFiClientSecure.h)
  client.setTimeout(8000);

  HTTPClient http;
  http.setUserAgent("SterownikCO-ESP32");
  http.setTimeout(8000);

  if (!http.begin(client, otaGithubApiUrl())) {
    bladOut = "http.begin() nieudane";
    return false;
  }

  serwisujTWDTJesliZarejestrowany();
  int kodHttp = http.GET();
  serwisujTWDTJesliZarejestrowany();

  if (kodHttp != 200) {
    bladOut = "GitHub API zwrocilo kod " + String(kodHttp);
    http.end();
    return false;
  }

  String body = http.getString();
  http.end();
  serwisujTWDTJesliZarejestrowany();

  // Parsowanie reczne (bez ArduinoJson) — ten sam styl co pollTelegramCommands()
  // nizej: szukamy "tag_name":"..." bezposrednio w tekscie odpowiedzi.
  // [SYNC-OTA/11.1, ta sesja] Punkt 11.1 planu (obawa o za maly bufor
  // ArduinoJson przy Release z 2 assetami zamiast 1) NIE DOTYCZY tej
  // funkcji — nie ma tu zadnego StaticJsonDocument/bufora o stalym
  // rozmiarze. body = http.getString() rosnie dynamicznie (String, nie
  // sztywny bufor), a szukane pole tag_name wystepuje w JSON-ie blisko
  // poczatku, niezaleznie od tego, ile assetow ma tablica "assets" dalej
  // w dokumencie — wiekszy Release (wiecej assetow) nie ma na to wplywu.
  // Punkt 11.1 zamkniety jako nieaktualny dla tej implementacji.
  int p = body.indexOf("\"tag_name\":\"");
  if (p < 0) { bladOut = "Brak pola tag_name w odpowiedzi"; return false; }
  p += strlen("\"tag_name\":\"");
  int e = body.indexOf('"', p);
  if (e < 0) { bladOut = "Nie udalo sie sparsowac tag_name"; return false; }

  tagOut = body.substring(p, e);
  return true;
}

// [FIX-OTA-DOWNGRADE, ta sesja] Porownanie wersji semver (MAJOR.MINOR.PATCH),
// NIE leksykograficzne na stringu (np. "v10.0.0" wypadaloby PRZED "v9.0.0"
// przy zwyklym porownaniu tekstu). Akceptuje opcjonalny prefiks 'v'/'V' i
// brakujace segmenty (np. "v2.2" jak "v2.2.0"). Zwraca: >0 gdy a NOWSZA niz
// b, 0 gdy identyczne, <0 gdy a STARSZA niz b. Uzycie: case TG_UPDATE, gdzie
// zastapilo warunek "tag == String(FIRMWARE_VERSION)", ktory nie odrozial
// "starszy tag" od "nowszy tag" - patrz Problem/Przyczyna przy [v2.2.3] w
// CHANGELOG na samej gorze pliku.
int porownajWersje(const String &a, const String &b) {
  auto segment = [](const String &s, int idx) -> long {
    String v = s;
    if (v.length() && (v[0] == 'v' || v[0] == 'V')) v = v.substring(1);
    int start = 0;
    for (int i = 0; i < idx; i++) {
      int dot = v.indexOf('.', start);
      if (dot < 0) return 0;              // brak tego segmentu = 0
      start = dot + 1;
    }
    int dot = v.indexOf('.', start);
    String part = (dot < 0) ? v.substring(start) : v.substring(start, dot);
    return part.toInt();                  // toInt() zwraca 0 dla nie-liczbowego wejscia
  };
  for (int i = 0; i < 3; i++) {
    long va = segment(a, i);
    long vb = segment(b, i);
    if (va != vb) return (va > vb) ? 1 : -1;
  }
  return 0;
}

// --- OTA GitHub - pobierz firmware.bin z Release o podanym tagu i zaflashuj ---
// httpUpdate.update() w tle sam woła Update.begin()/write()/end() (ta sama
// biblioteka co w handlerze /ota-upload z przegladarki) i sam obsluguje
// przekierowanie 302 na inny host (setFollowRedirects) — to jedyny powod
// uzycia HTTPUpdate zamiast recznego strumieniowania jak w pollTelegramCommands.
// Karmienie WDT: onProgress() jest wolane regularnie w trakcie zapisu do
// flash — feed tam wystarcza, bo tgTaskFn (wywolujacy ta funkcje) jest juz
// zarejestrowany w Task WDT (esp_task_wdt_add w tgTaskFn).
// [SYNC-OTA/11.4, ta sesja] Parametr tag: DODANY. Wywolujacy (case TG_UPDATE)
// ma go juz w rece z wczesniejszego sprawdzNajnowszaWersjeGithub() — patrz
// otaGithubDownloadUrl() wyzej, dlaczego to teraz konieczne.
bool wykonajAktualizacjeOTA(const String &tag, String &bladOut) {
  WiFiClientSecure client;
  client.setInsecure();
  client.setTimeout(15000);

  httpUpdate.rebootOnUpdate(false);  // restart robimy sami, PO wyslaniu wiadomosci na Telegram
  httpUpdate.setFollowRedirects(HTTPC_FORCE_FOLLOW_REDIRECTS);
  httpUpdate.onProgress([](int cur, int total) {
    serwisujTWDTJesliZarejestrowany();
  });

  serwisujTWDTJesliZarejestrowany();
  t_httpUpdate_return wynik = httpUpdate.update(client, otaGithubDownloadUrl(tag));
  serwisujTWDTJesliZarejestrowany();

  switch (wynik) {
    case HTTP_UPDATE_FAILED:
      bladOut = "Blad OTA (" + String(httpUpdate.getLastErrorString().c_str()) + ")";
      return false;
    case HTTP_UPDATE_NO_UPDATES:
      bladOut = "Serwer zglosil 'brak aktualizacji'";
      return false;
    case HTTP_UPDATE_OK:
      return true;
  }
  bladOut = "Nieznany wynik HTTPUpdate";
  return false;
}

// --- OTA PANEL: adres pobrania assetu firmware_panel.bin dla PODANEGO tagu ---
// [SYNC-OTA/11.4, ta sesja] Ta sama zmiana co otaGithubDownloadUrl() dla
// centrali wyzej — /releases/download/{tag}/{plik} zamiast
// /releases/latest/download/{plik}, zeby nie polegac na resolwowaniu
// "latest" (ktore cicho pomija prerelease). tag_name nadal wspolny z
// centrala — sprawdzNajnowszaWersjeGithub() (wyzej) juz go zwraca, wiec
// NIE dublujemy zapytania do api.github.com (BAGNO 1.1, rate limit).
String otaGithubDownloadUrlPanel(const String &tag) {
  return "https://github.com/" + String(GITHUB_OWNER) + "/" + String(GITHUB_REPO) +
         "/releases/download/" + tag + "/" + String(GITHUB_ASSET_PANEL);
}

// --- OTA PANEL: pobierz firmware_panel.bin z GitHub i zapisz na LittleFS ---
// Celowo NIE uzywamy HTTPUpdate (to flashowaloby CENTRALE) — zwykly
// HTTPClient + reczne strumieniowanie do pliku, tak jak juz robi to
// pollTelegramCommands() gdzie indziej w tym pliku. Wzorzec "zapisz do .tmp,
// zweryfikuj, dopiero potem rename()" — BAGNO 2.1 — chroni panel przed
// pobraniem na wpol zapisanego pliku, gdyby akurat w tej chwili odpytal
// /panel-ota.bin. Walidacja pierwszego bajtu (0xE9, naglowek obrazu ESP32)
// i rozmiaru wzgledem Content-Length — BAGNO 1.3.
// [SYNC-OTA/11.4, ta sesja] Parametr tag: DODANY, patrz uzasadnienie przy
// otaGithubDownloadUrlPanel() wyzej.
bool pobierzFirmwarePanelaZGithub(const String &tag, String &bladOut) {
  WiFiClientSecure client;
  client.setInsecure();
  client.setTimeout(15000);

  HTTPClient http;
  http.setUserAgent("SterownikCO-ESP32");
  http.setTimeout(15000);
  http.setFollowRedirects(HTTPC_FORCE_FOLLOW_REDIRECTS); // github.com -> releases.githubusercontent.com (BAGNO 1.4)

  if (!http.begin(client, otaGithubDownloadUrlPanel(tag))) {
    bladOut = "http.begin() nieudane (panel)";
    return false;
  }

  serwisujTWDTJesliZarejestrowany();
  int kodHttp = http.GET();
  if (kodHttp != 200) {
    bladOut = "Pobieranie firmware panelu zwrocilo kod " + String(kodHttp);
    http.end();
    return false;
  }

  int oczekiwanyRozmiar = http.getSize(); // -1 jesli serwer nie podal Content-Length
  const char* sciezkaTmp = "/panel_firmware.bin.tmp";
  const char* sciezkaDocelowa = "/panel_firmware.bin";

  // [F2.8] Twardy limit obrazu panelu i pre-check miejsca na staging.
  if (oczekiwanyRozmiar > 0 && (size_t)oczekiwanyRozmiar > FS_PANEL_FIRMWARE_MAX_B) {
    bladOut = "Firmware panelu za duzy: " + String((unsigned long)oczekiwanyRozmiar) +
              " B > limit " + String((unsigned long)FS_PANEL_FIRMWARE_MAX_B) + " B";
    http.end();
    return false;
  }

  FsQuotaHard quotaHard;
  if (!fsQuotaHardEvaluate(quotaHard)) {
    bladOut = "Nie mozna policzyc hard quota LittleFS";
    http.end();
    return false;
  }
  const size_t stagingCheckBytes = (oczekiwanyRozmiar > 0)
      ? (size_t)oczekiwanyRozmiar : FS_PANEL_STAGING_MAX_B;
  if (!quotaHard.ok || stagingCheckBytes > quotaHard.availableQuotaBytes) {
    bladOut = "Brak miejsca na bezpieczny staging panelu: potrzebne " +
              String((unsigned long)stagingCheckBytes) + " B, quota " +
              String((unsigned long)quotaHard.availableQuotaBytes) + " B";
    http.end();
    return false;
  }

  // [FIX-WSPOLBIEZNOSC] Krotkie operacje metadanych (remove starego .tmp +
  // open nowego) pod logMutex, jak wszedzie indziej w tym pliku. Sam
  // strumieniowy zapis w petli nizej NIE jest owiniety mutexem celowo:
  // pobieranie firmware panelu moze trwac dlugo (LVGL/TFT bywa wiekszy), a
  // trzymanie logMutex przez caly ten czas zablokowaloby
  // zapiszLogKrytyczny() na Core 1 (sciezki alarmowe/interlock) na cala
  // dlugosc pobierania — ten sam kompromis co przy strumieniu w
  // sendTelegramDocument().
  bool tmpGotowy = false;
  File f;
  if (logMutex && xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) == pdTRUE) {
    if (LittleFS.exists(sciezkaTmp)) LittleFS.remove(sciezkaTmp);
    f = LittleFS.open(sciezkaTmp, "w");
    tmpGotowy = (bool)f;
    xSemaphoreGive(logMutex);
  }
  if (!tmpGotowy) {
    bladOut = "Nie udalo sie otworzyc " + String(sciezkaTmp) + " do zapisu (lub logMutex zajety)";
    http.end();
    return false;
  }

  WiFiClient* strumien = http.getStreamPtr();
  uint8_t bufor[512];
  size_t zapisano = 0;
  bool pierwszyBajtOk = true;
  unsigned long ostatniByte = millis();

  while (http.connected() && (oczekiwanyRozmiar < 0 || (int)zapisano < oczekiwanyRozmiar)) {
    serwisujTWDTJesliZarejestrowany(); // pobieranie moze trwac dlugo (firmware panelu z LVGL/TFT bywa wiekszy) — patrz BAGNO 3.4/analogia
    size_t dostepne = strumien->available();
    if (dostepne == 0) {
      if (millis() - ostatniByte > 15000) break; // 15s ciszy = koniec/blad polaczenia
      delay(10);
      continue;
    }
    // [FIX-BUILD, 2026-09-13] min(size_t, size_t) bylo niejednoznaczne dla
    // kompilatora (sizeof() dopasowywalo sie do innego typu niz dostepne) -
    // jawne rzutowanie obu stron usuwa niejednoznacznosc przeciazenia.
    size_t doOdczytu = min((size_t)dostepne, (size_t)sizeof(bufor));
    int n = strumien->readBytes(bufor, doOdczytu);
    if (n <= 0) break;
    if (zapisano == 0 && n > 0 && (uint8_t)bufor[0] != 0xE9) {
      pierwszyBajtOk = false; // BAGNO 1.3 — zly Asset/uszkodzony plik, ale dokonczmy odczyt zeby nie zostawic polaczenia w polowie
    }
    if (zapisano + (size_t)n > FS_PANEL_FIRMWARE_MAX_B) {
      pierwszyBajtOk = false;
      bladOut = "Firmware panelu przekroczyl limit 2 MiB podczas pobierania";
      break;
    }
    size_t zapisanoChunk = f.write(bufor, (size_t)n);
    if (zapisanoChunk != (size_t)n) {
      pierwszyBajtOk = false;
      bladOut = "Blad zapisu firmware panelu na LittleFS";
      break;
    }
    zapisano += (size_t)n;
    ostatniByte = millis();
  }
  f.close();
  http.end();
  serwisujTWDTJesliZarejestrowany();

  // [FIX-WSPOLBIEZNOSC] Sprzatanie .tmp przy bledzie — te same krotkie
  // operacje metadanych, ten sam mutex.
  if (!pierwszyBajtOk) {
    if (bladOut.length() == 0) {
      bladOut = "Zly naglowek pliku (oczekiwano 0xE9 na starcie) — zly Asset albo uszkodzony Release";
    }
    if (logMutex && xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) == pdTRUE) { LittleFS.remove(sciezkaTmp); xSemaphoreGive(logMutex); }
    return false;
  }
  if (oczekiwanyRozmiar > 0 && (int)zapisano != oczekiwanyRozmiar) {
    bladOut = "Rozmiar niezgodny: pobrano " + String(zapisano) + " z oczekiwanych " + String(oczekiwanyRozmiar);
    if (logMutex && xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) == pdTRUE) { LittleFS.remove(sciezkaTmp); xSemaphoreGive(logMutex); }
    return false;
  }
  if (zapisano == 0) {
    bladOut = "Pobrano 0 bajtow";
    if (logMutex && xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) == pdTRUE) { LittleFS.remove(sciezkaTmp); xSemaphoreGive(logMutex); }
    return false;
  }

  // [FIX-WSPOLBIEZNOSC] Rotacja (remove starego + rename) pod logMutex —
  // ten sam wzorzec co logFsSizeGuard(). g_panelFirmwareSize aktualizowany
  // z "zapisano" (dokladna liczba bajtow faktycznie zapisanych w petli
  // wyzej), wewnatrz tej samej sekcji.
  bool rotacjaOk = false;
  if (logMutex && xSemaphoreTake(logMutex, pdMS_TO_TICKS(200)) == pdTRUE) {
    if (LittleFS.exists(sciezkaDocelowa)) LittleFS.remove(sciezkaDocelowa);
    rotacjaOk = LittleFS.rename(sciezkaTmp, sciezkaDocelowa);
    if (rotacjaOk) g_panelFirmwareSize = zapisano;
    xSemaphoreGive(logMutex);
  }
  if (!rotacjaOk) {
    bladOut = "rename() na LittleFS nieudany (lub logMutex zajety)";
    return false;
  }

  DLOGF(DC_OTA, DL_INFO, "OTA-PANEL zdarzenie=pobrano_firmware rozmiar=%u", (unsigned)zapisano);
  return true;
}

// --- TELEGRAM - odbierz i obsluz nowe komendy (getUpdates, long-poll offset) ---
// Minimalny zakres na start (Punkt 6a, jak ustalono): /status. Kolejne
// komendy (restart, logi, wlacz/wylacz powiadomienia...) doloz analogicznie,
// wzorem pollTelegramCommands() w Rybach.
// [TG-LONGPOLL, 26.07.2026] Opcja B, Czesc 2 PLAN_CZESTOTLIWOSC_ZADAN.md:
// prawdziwy long-poll (timeout=25) zamiast timeout=0 co ~3s. Wolane teraz
// WYLACZNIE z wlasnego zadania tgPollTaskFn (nizej), nie z tgTaskFn — inaczej
// blokada do ~30s (TG_POLL_WAIT_MS) zamrozilaby tam wysylke do Firebase.
// TG_POLL_WAIT_MS > TG_POLL_TIMEOUT_S*1000 celowo — to Telegram (nie my)
// odmierza timeout servera, margines jest na sam czas podrozy pakietu.
static const int           TG_POLL_TIMEOUT_S = 25;
static const unsigned long TG_POLL_WAIT_MS   = 30000UL;

// --- TELEGRAM - wrzuc komende do tgCmdQueue, z fallbackiem gdy sie nie da ---
// [CZESC 3, B8] Wspolny helper dla pollTelegramCommands() (komendy tekstowe
// i przyciski) — jedno miejsce zamiast wielu kopii tego samego
// if(!tgCmdQueue || xQueueSend(...) != pdTRUE) fallback. /status i /start
// maja WLASNY, nieco inny fallback (bezposrednie wykonanie zamiast
// komunikatu o bledzie) — ustalony juz w Czesci 2, celowo nieruszany.
// [REMOTE-FB-PROVISION] Pelny tekst ostatniej komendy provisioningowej.
// Dostep jest serializowany przez tgCmdQueue/tgTask; nie logujemy tej wartosci.
static String tgQueuedText = "";

void tgKolejkujAlboOdpowiedzBledem(TgDeferCmd cmd, uint32_t arg = 0) {
  TgQueuedCmd item{cmd, arg};
  if (!tgCmdQueue || xQueueSend(tgCmdQueue, &item, 0) != pdTRUE) {
    DLOG(DC_TELEGRAM, DL_WARN, F("TG msg=\"tgCmdQueue pelna/niedostepna - komenda pominieta\""));
    sendTelegramMessage(F("Za duzo komend na raz - sprobuj ponownie za chwile."));
  }
}

void pollTelegramCommands() {
  if (!tgEnabled) return;
  diagCheckpoint(DIAG_TASK_TGPOLL, DIAG_OP_TG_CONNECT, DIAG_STAGE_BEFORE);
  if (!tgEnsureConnected(tgPollClient, tgPollClientReady, tgPollClientLastUse)) {
    diagCheckpoint(DIAG_TASK_TGPOLL, DIAG_OP_TG_CONNECT, DIAG_STAGE_ERROR);
    return;
  }
  diagCheckpoint(DIAG_TASK_TGPOLL, DIAG_OP_TG_CONNECT, DIAG_STAGE_AFTER);

  String url = "/bot" + tgBotToken + "/getUpdates?offset=" + String(tgLastUpdateId + 1) +
               "&timeout=" + String(TG_POLL_TIMEOUT_S);

  serwisujTWDTJesliZarejestrowany();
  // [AUDYT-PKT1] tgWriteGuard() na tgPollClient — domkniecie rekomendacji #4
  // z audytu (jedyny print() poza tgPostJson()/sendTelegramDocument(), ktory
  // dotad nie byl objety guardem).
  if (!tgWriteGuard(tgPollClient)) {
    DLOG(DC_TELEGRAM, DL_WARN, F("TG-POLL zdarzenie=WRITEGUARD etap=getUpdates msg=\"gniazdo niezapisywalne - pomijam poll, wymuszam reconnect\""));
    tgPollClient.stop();
    tgPollClientReady = false;
    return;
  }
  diagCheckpoint(DIAG_TASK_TGPOLL, DIAG_OP_TG_POST, DIAG_STAGE_BEFORE);
  tgPollClient.print(String("GET ") + url + " HTTP/1.1\r\n" +
                 "Host: " + TG_HOST + "\r\n" +
                 "Connection: keep-alive\r\n\r\n");
  diagCheckpoint(DIAG_TASK_TGPOLL, DIAG_OP_TG_POST, DIAG_STAGE_AFTER);

  unsigned long start = millis();
  diagCheckpoint(DIAG_TASK_TGPOLL, DIAG_OP_TG_POLL_WAIT, DIAG_STAGE_BEFORE);
  while (tgPollClient.connected() && !tgPollClient.available() && millis() - start < TG_POLL_WAIT_MS) {
    serwisujTWDTJesliZarejestrowany();
    delay(10);
  }

  diagCheckpoint(DIAG_TASK_TGPOLL, DIAG_OP_TG_POLL_WAIT, DIAG_STAGE_AFTER);

  String body;
  body.reserve(1024);
  while (tgPollClient.available()) {
    body += (char)tgPollClient.read();
    if (body.length() % 64 == 0) serwisujTWDTJesliZarejestrowany();
  }
  tgPollClientLastUse = millis();
  if (body.length() == 0) return;

  // Parsowanie reczne (bez ArduinoJson), wzorem Ryb — kazdy update_id
  // wyznacza "chunk" [idEnd, chunkEnd), w ktorym szukamy albo
  // "callback_query" (klikniety przycisk menu), albo "text" (komenda
  // tekstowa). "id":" (z cudzyslowem) w callback_query dopasowuje
  // WYLACZNIE wlasne id callback_query (string) — "from":{"id":...} i
  // "message":{"chat":{"id":...}}} to liczby bez cudzyslowu, wiec nie
  // pasuja do wzorca "id":". Analogicznie "data":" dopasowuje tylko pole
  // callback_query.data, nie "callback_data" wewnatrz echa reply_markup
  // (rozne stringi: "data" nie jest sufiksem "callback_data" — brak
  // cudzyslowu przed "data" w "callback_data").
  int pos = 0;
  while (true) {
    int idPos = body.indexOf("\"update_id\":", pos);
    if (idPos < 0) break;
    idPos += strlen("\"update_id\":");
    int idEnd = body.indexOf(',', idPos);
    if (idEnd < 0) break;
    long updateId = body.substring(idPos, idEnd).toInt();
    if (updateId > tgLastUpdateId) tgLastUpdateId = updateId;

    int nextIdPos = body.indexOf("\"update_id\":", idEnd);
    int chunkEnd  = (nextIdPos < 0) ? (int)body.length() : nextIdPos;

    // ── callback_query: kliknieto przycisk menu ──
    int cbqPos = body.indexOf("\"callback_query\"", idEnd);
    if (cbqPos >= 0 && cbqPos < chunkEnd) {
      String cbId, cbData;
      int idQPos = body.indexOf("\"id\":\"", cbqPos);
      if (idQPos >= 0 && idQPos < chunkEnd) {
        idQPos += strlen("\"id\":\"");
        int idQEnd = body.indexOf("\"", idQPos);
        if (idQEnd > idQPos && idQEnd < chunkEnd) cbId = body.substring(idQPos, idQEnd);
      }
      int dataPos = body.indexOf("\"data\":\"", cbqPos);
      if (dataPos >= 0 && dataPos < chunkEnd) {
        dataPos += strlen("\"data\":\"");
        int dataEnd = body.indexOf("\"", dataPos);
        if (dataEnd > dataPos && dataEnd < chunkEnd) cbData = body.substring(dataPos, dataEnd);
      }

      // Bez tego Telegram pokazuje "zegarek" na przycisku do timeoutu —
      // odpowiadamy ZAWSZE, niezaleznie od tego, czy cbData sie rozpoznalo.
      if (cbId.length() > 0) answerTelegramCallback(cbId);

      if (cbData == "clr_logs_no") {
        // Anulowanie — obsluzone od razu, bez kolejki (nic nie zmienia w
        // stanie urzadzenia, wiec nie ma powodu czekac na tgTaskFn).
        sendTelegramMessage(F("Anulowano czyszczenie logow."));
      } else if (cbData == "restart_no") {
        sendTelegramMessage(F("Anulowano restart."));
      } else if (cbData.length() > 0) {
        TgDeferCmd doKolejki = TG_NONE;
        uint32_t doKolejkiArg = 0;
        if      (cbData == "menu")             doKolejki = TG_MENU;
        else if (cbData == "menu_sterowanie")   doKolejki = TG_MENU_STEROWANIE;
        else if (cbData == "menu_alarmy")       doKolejki = TG_MENU_ALARMY;
        else if (cbData == "menu_dane")         doKolejki = TG_MENU_DANE;
        else if (cbData == "menu_diag")         doKolejki = TG_MENU_DIAGNOSTYKA;
        else if (cbData == "menu_ota")          doKolejki = TG_MENU_OTA;
        else if (cbData == "diag_report")       doKolejki = TG_DIAGNOSTYKA;
        else if (cbData == "spoolrt_report") doKolejki = TG_SPOOL_RUNTIME_REPORT;
        else if (cbData == "spoolrt_arm")    doKolejki = TG_SPOOL_RUNTIME_ARM;
        else if (cbData == "spoolrt_stop")   doKolejki = TG_SPOOL_RUNTIME_STOP;
        else if (cbData == "telemetry_diag")    doKolejki = TG_TELEMETRY_DIAG;
        else if (cbData == "spool_test_write") doKolejki = TG_SPOOL_TEST_WRITE;
        else if (cbData == "spool_test_verify") doKolejki = TG_SPOOL_TEST_VERIFY;
        else if (cbData == "spool_open_write") doKolejki = TG_SPOOL_OPEN_WRITE;
        else if (cbData == "spool_open_recover") doKolejki = TG_SPOOL_OPEN_RECOVER;
        else if (cbData == "spool_powerloss_prep") doKolejki = TG_SPOOL_POWERLOSS_PREP;
        else if (cbData == "spool_powerloss_recover") doKolejki = TG_SPOOL_POWERLOSS_RECOVER;
        else if (cbData == "spool_recovery_continue") doKolejki = TG_SPOOL_RECOVERY_CONTINUE;
        else if (cbData == "spool_full_page") doKolejki = TG_SPOOL_FULL_PAGE;
        else if (cbData == "spool252_mirror_arm") doKolejki = TG_SPOOL_TELEMETRY_MIRROR_ARM;
        else if (cbData == "spool252_mirror_verify") doKolejki = TG_SPOOL_TELEMETRY_MIRROR_VERIFY;
        else if (cbData == "status")           doKolejki = TG_STATUS;
        else if (cbData == "temp")             doKolejki = TG_TEMP;
        else if (cbData == "serwa")            doKolejki = TG_SERWA;
        else if (cbData == "logi")             doKolejki = TG_LOGS;
        else if (cbData == "logi_sd")          doKolejki = TG_LOGS_SD;
        else if (cbData == "logi_krytyczne")   doKolejki = TG_LOGS_KRYTYCZNE;
        else if (cbData == "historia")         doKolejki = TG_HIST;
        else if (cbData == "solar_archive")    doKolejki = TG_SOLAR_ARCHIVE;
        else if (cbData == "coredump_latest")   doKolejki = TG_COREDUMP;
        else if (cbData == "coredump_list")     doKolejki = TG_COREDUMP_LIST;
        else if (cbData.startsWith("coredump_boot_")) {
          String arg = cbData.substring(strlen("coredump_boot_"));
          arg.trim();
          bool digitsOnly = arg.length() > 0;
          for (size_t i = 0; digitsOnly && i < arg.length(); ++i) {
            if (arg[i] < '0' || arg[i] > '9') digitsOnly = false;
          }
          if (digitsOnly) {
            unsigned long parsed = strtoul(arg.c_str(), nullptr, 10);
            if (parsed > 0 && parsed <= 0xFFFFFFFFUL) {
              doKolejki = TG_COREDUMP_BOOT;
              doKolejkiArg = (uint32_t)parsed;
            }
          }
        }
        else if (cbData == "pompa_wl")         doKolejki = TG_POMPA_WL;
        else if (cbData == "pompa_wyl")        doKolejki = TG_POMPA_WYL;
        else if (cbData == "tryb_menu")        doKolejki = TG_TRYB_MENU;
        else if (cbData == "tryb_auto")        doKolejki = TG_TRYB_AUTO;
        else if (cbData == "tryb_reczny")      doKolejki = TG_TRYB_RECZNY;
        else if (cbData == "tryb_bezpieczny")  doKolejki = TG_TRYB_BEZPIECZNY;
        else if (cbData == "cisza")            doKolejki = TG_CISZA;
        else if (cbData == "reset_alarmy")     doKolejki = TG_RESET_ALARMY;
        else if (cbData == "clr_logs_confirm") doKolejki = TG_CLR_LOGS_CONFIRM;
        else if (cbData == "clr_logs_yes")     doKolejki = TG_CLR_LOGS_DO;
        else if (cbData == "restart_confirm")  doKolejki = TG_RESTART_CONFIRM;
        else if (cbData == "restart_yes")      doKolejki = TG_RESTART_DO;
        else if (cbData == "notif_toggle")     doKolejki = TG_NOTIF_TOGGLE;
        else if (cbData == "update")           doKolejki = TG_UPDATE;
        else if (cbData == "update_panel")     doKolejki = TG_UPDATE_PANEL;
        // nieznane cbData -> doKolejki zostaje TG_NONE, nic sie nie dzieje
        // (juz odpowiedzielismy answerTelegramCallback() wyzej)

        if (doKolejki != TG_NONE) tgKolejkujAlboOdpowiedzBledem(doKolejki, doKolejkiArg);
      }
    }
    // ── message: wiadomosc tekstowa (tylko gdy NIE bylo callback_query) ──
    else {
      int textPos = body.indexOf("\"text\":\"", idEnd);
      if (textPos >= 0 && textPos < chunkEnd) {
        textPos += strlen("\"text\":\"");
        int textEnd = body.indexOf("\"", textPos);
        String cmd = (textEnd < 0) ? "" : body.substring(textPos, textEnd);
        cmd.trim();

        if (cmd.startsWith("/fbprov|")) {
          // Credential przechodzi przez TLS Telegrama i nie trafia do Serial/logow.
          // Wrzucamy tresc do bufora RAM, a do kolejki tylko typ komendy.
          tgQueuedText = cmd;
          tgKolejkujAlboOdpowiedzBledem(TG_FIREBASE_PROVISION);
        } else if (cmd == "/status") {
          // [ETAP B, B2 — ustalone w Czesci 2] Wlasny fallback (bezposrednie
          // wyslanie raportu), celowo inny niz tgKolejkujAlboOdpowiedzBledem()
          // — nieruszane, zeby nie zmieniac juz przetestowanego zachowania.
          TgQueuedCmd doKolejki{TG_STATUS, 0};
          if (!tgCmdQueue || xQueueSend(tgCmdQueue, &doKolejki, 0) != pdTRUE) {
            sendTelegramMessage(buildTelegramStatusReport());
          }
        } else if (cmd == "/start" || cmd == "/menu" || cmd == "/help") {
          // [CZESC 3, B8] /start pokazywal dotychczas status (Czesc 2) — od
          // teraz, gdy menu juz istnieje, pokazuje menu (tak jak w Rybach).
          // /status zostaje osobna komenda dla samego raportu.
          TgQueuedCmd doKolejki{TG_MENU, 0};
          if (!tgCmdQueue || xQueueSend(tgCmdQueue, &doKolejki, 0) != pdTRUE) {
            sendTelegramInlineMenu();
          }
        } else if (cmd == "/version") {
          sendTelegramMessage("Obecna wersja: " + String(FIRMWARE_VERSION));
        } else if (cmd == "/cisza") {
          tgKolejkujAlboOdpowiedzBledem(TG_CISZA);
        } else if (cmd == "/logi" || cmd == "/sendlogs") {
          tgKolejkujAlboOdpowiedzBledem(TG_LOGS);
        } else if (cmd == "/log_krytyczny" || cmd == "/logikrytyczne" || cmd == "/logkrytyczny") {
          tgKolejkujAlboOdpowiedzBledem(TG_LOGS_KRYTYCZNE);
        } else if (cmd == "/logi_sd") {
          // [PLAN_SD_LOGI_AWARYJNE.md, Czesc 5] analogicznie do /logi wyzej.
          tgKolejkujAlboOdpowiedzBledem(TG_LOGS_SD);
        } else if (cmd == "/coredumpy") {
          // [COREDUMP, v3.11.0] wybieramy latest po trwalym seq.
          tgKolejkujAlboOdpowiedzBledem(TG_COREDUMP);
        } else if (cmd.startsWith("/coredumpy ")) {
          // [COREDUMP, v3.11.2] /coredumpy <boot> wybiera konkretny boot.
          String arg = cmd.substring(strlen("/coredumpy "));
          arg.trim();
          bool digitsOnly = arg.length() > 0;
          for (size_t i = 0; digitsOnly && i < arg.length(); ++i) {
            if (arg[i] < '0' || arg[i] > '9') digitsOnly = false;
          }
          if (!digitsOnly) {
            sendTelegramMessage(F("Uzycie: /coredumpy albo /coredumpy <boot> (np. /coredumpy 8)"));
          } else {
            unsigned long parsed = strtoul(arg.c_str(), nullptr, 10);
            if (parsed > 0xFFFFFFFFUL) {
              sendTelegramMessage(F("Numer boot jest za duzy."));
            } else {
              tgKolejkujAlboOdpowiedzBledem(TG_COREDUMP_BOOT, (uint32_t)parsed);
            }
          }
        } else if (cmd == "/coredumplist") {
          tgKolejkujAlboOdpowiedzBledem(TG_COREDUMP_LIST);
        } else if (cmd == "/spooltest") {
          sendTelegramMessage(F("R245: wpisz /spooltest TAK aby zapisac kontrolowana strone Spool V2 na LittleFS."));
        } else if (cmd == "/spooltest TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_TEST_WRITE);
        } else if (cmd == "/spoolverify") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_TEST_VERIFY);
        } else if (cmd == "/spoolopen") {
          sendTelegramMessage(F("R246: wpisz /spoolopen TAK aby zapisac otwarta strone Spool V2 bez footer commit."));
        } else if (cmd == "/spoolopen TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_OPEN_WRITE);
        } else if (cmd == "/spoolrecover") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_OPEN_RECOVER);
        } else if (cmd == "/spool247") {
          sendTelegramMessage(F("R247: wpisz /spool247 TAK tylko na pustej plytce testowej. Potem odlacz zasilanie w oknie 15 s."));
        } else if (cmd == "/spool247 TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_POWERLOSS_PREP);
        } else if (cmd == "/spool247recover") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_POWERLOSS_RECOVER);
        } else if (cmd == "/spool248repair") {
          sendTelegramMessage(F("R248: wpisz /spool248repair TAK tylko na lokalnej plytce po R247 PASS; odrzucony zostanie niepelny ogon i zapisany nowy rekord #3."));
        } else if (cmd == "/spool248repair TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_RECOVERY_CONTINUE);
        } else if (cmd == "/spool249") {
          sendTelegramMessage(F("R249: wpisz /spool249 TAK tylko na lokalnej plytce. Zapisze pelna strone 768 rekordow + footer commit."));
        } else if (cmd == "/spool249 TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_FULL_PAGE);
        } else if (cmd == "/spool250") {
          sendTelegramMessage(F("R250: wpisz /spool250 TAK tylko na lokalnej plytce. Przygotuje 4 rekordy i celowo uszkodzi rekord #2."));
        } else if (cmd == "/spool250 TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_CRC_CORRUPT_WRITE);
        } else if (cmd == "/spool250recover") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_CRC_CORRUPT_RECOVER);
        } else if (cmd == "/spool251") {
          sendTelegramMessage(F("R251: wpisz /spool251 TAK tylko na lokalnej plytce. Sprawdzi granice hard quota bez zapisywania megabajtow danych."));
        } else if (cmd == "/spool251 TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_QUOTA_BOUNDARY);
        } else if (cmd == "/spool252") {
          sendTelegramMessage(F("R252: wpisz /spool252 TAK tylko na lokalnej plytce. Uzbroi mirror rzeczywistych probek telemetrycznych do /telemetry_spool/r252_telemetry_mirror.bin."));
        } else if (cmd == "/spool252 TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_TELEMETRY_MIRROR_ARM);
        } else if (cmd == "/spool252verify") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_TELEMETRY_MIRROR_VERIFY);
        } else if (cmd == "/spoolbatch") {
          sendTelegramMessage(F("R253-R262: wpisz /spoolbatch TAK tylko na lokalnej plytce. Uruchomi 10 testow rdzenia Spool V2."));
        } else if (cmd == "/spoolbatch TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_BATCH);
        } else if (cmd == "/spoolbatch2") {
          sendTelegramMessage(F("R263-R272: wpisz /spoolbatch2 TAK tylko na lokalnej plytce. Uruchomi 10 testow semantyki Spool V2."));
        } else if (cmd == "/spoolbatch2 TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_BATCH2);
        } else if (cmd == "/spoolbatch3") {
          sendTelegramMessage(F("R273-R282: wpisz /spoolbatch3 TAK tylko na lokalnej plytce. Testuje integracje producenta telemetryki z adapterem Spool V2."));
        } else if (cmd == "/spoolbatch3 TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_BATCH3);
        } else if (cmd == "/spoolreplay") {
          sendTelegramMessage(F("R301-R312: wpisz /spoolreplay TAK tylko na lokalnej plytce. Replay/ACK/delete + fault batch."));
        } else if (cmd == "/spoolreplay TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_REPLAY_BATCH);
        } else if (cmd == "/spoolfault") {
          sendTelegramMessage(F("R313-R324: wpisz /spoolfault TAK tylko na lokalnej plytce. Storage fault/recovery matrix."));
        } else if (cmd == "/spoolfault TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_FAULT_BATCH);
        } else if (cmd == "/spoolg") {
          sendTelegramMessage(F("R325-R334: wpisz /spoolg TAK tylko na lokalnej plytce. Commit G: rzeczywisty TelemetryRing -> trwały Persistent Spool V2."));
        } else if (cmd == "/spoolg TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SPOOL_COMMIT_G_BATCH);
        } else if (cmd == "/spoolrt") {
          sendTelegramMessage(spoolRuntimeBuildReport());
        } else if (cmd == "/spoolrt TAK") {
          String wynik;
          if (spoolRuntimeArm(wynik)) sendTelegramMessage(String("G2: ") + wynik);
          else sendTelegramMessage(String("G2: ARM FAIL — ") + wynik);
        } else if (cmd == "/spoolrt STOP") {
          String wynik;
          spoolRuntimeStop(wynik);
          sendTelegramMessage(String("G2: ") + wynik);
        } else if (cmd == "/securityh") {
          sendTelegramMessage(F("R335-R344: wpisz /securityh TAK tylko na lokalnej plytce. H1: Firebase TLS verification + brak domyslnego sekretu."));
        } else if (cmd == "/securityh TAK") {
          tgKolejkujAlboOdpowiedzBledem(TG_SECURITY_H1_BATCH);
        } else if (cmd == "/securityh2") {
          sendTelegramMessage(F("R345-R356: wpisz /securityh2 TAK tylko na lokalnej plytce. H2: UserAuth z NVS + shadow /piec/devices/<uid>/...; bez migracji V1."));
        } else if (cmd == "/rtdbmega") {
          tgKolejkujAlboOdpowiedzBledem(TG_RTDB_INTEGRATION_BATCH);
        } else if (cmd == "/finalmega") {
          sendTelegramMessage(F("R380-R400: wpisz /finalmega TAK tylko na lokalnej plytce. Uruchomi caly duzy regression gate: spool + replay + Commit G + H1/H2 + RTDB + health."));
        } else if (cmd == "/finalmega TAK") {
          sendTelegramMessage(F("FINAL-MEGA: komenda przyjeta — uruchamiam R380-R399."));
          if (!finalMegaLaunchTask()) {
            sendTelegramMessage(F("FINAL-MEGA: nie uruchomiono worker'a (test juz trwa albo runtime jest zajety)."));
          }
        } else if (cmd == "/stabilitymega") {
          sendTelegramMessage(F("R401-R430: wpisz /stabilitymega TAK tylko na lokalnej plytce. Powtorzeniowy regression/stability mega bez celowego crashu."));
        } else if (cmd == "/stabilitymega TAK") {
          // [v3.31.21] Persistuj update_id PRZED startem workera. Po restarcie
          // Telegram moze zwrocic ten sam update, bo tgLastUpdateId jest tylko RAM.
          if (!stabilityMegaOznaczUpdateZuzyty(updateId)) {
            sendTelegramMessage(F("STABILITY-MEGA: ta komenda zostala juz obsluzona albo nie mozna jej trwale zapisac — test zablokowany."));
          } else {
            sendTelegramMessage(F("STABILITY-MEGA: komenda przyjeta — uruchamiam R401-R430."));
            if (!stabilityMegaLaunchTask()) {
              sendTelegramMessage(F("STABILITY-MEGA: nie uruchomiono worker'a (test trwa albo runtime jest zajety)."));
            }
          }
        } else if (cmd == "/recoverymega") {
          sendTelegramMessage(F("R431-R470: wpisz /recoverymega TAK tylko na lokalnej plytce. Nie flashuje OTA, nie resetuje urzadzenia; testuje recovery/OTA state/LittleFS/quota/coredump/boot oraz regresje koncowe."));
        } else if (cmd == "/recoverymega TAK") {
          sendTelegramMessage(F("RECOVERY-OTA-MEGA: komenda przyjeta — uruchamiam R431-R470."));
          if (!recoveryOtaMegaLaunchTask()) {
            sendTelegramMessage(F("RECOVERY-OTA-MEGA: nie uruchomiono worker'a (test trwa albo runtime jest zajety)."));
          }
        } else if (cmd == "/securityh2 TAK") {
          // [H2-WORKER-FIX, v3.29.3] ACK zostaje natychmiastowy, ale sam
          // batch NIE trafia juz do tgCmdQueue/tgTask. To rozdziela test H2
          // od glownej petli Telegrama: jesli tgTask jest zajety Firebase/WDT,
          // H2 nadal wystartuje, bo polling i worker sa niezalezne. Wynik
          // wysyla sam worker po zakonczeniu batcha.
          sendTelegramMessage(F("H2: komenda przyjeta — uruchamiam R345-R356."));
          if (!securityH2LaunchTask()) {
            sendTelegramMessage(F("H2: nie uruchomiono worker'a R345-R356 (test juz trwa albo brak zasobow)."));
          }
        } else if (cmd == "/testcrash") {
          // [COREDUMP-TEST-ARM, v3.31.10] /testcrash tylko UZBRAJA test na 60 s.
          // Sama komenda nie powoduje crasha. To chroni przed starym
          // /testcrash TAK zalegajacym w getUpdates po restarcie.
          g_testCrashArmed = true;
          g_testCrashArmedMs = millis();
          sendTelegramMessage(F("Test coredumpu uzbrojony na 60 s. Teraz wpisz /testcrash TAK."));
        } else if (cmd == "/testcrash TAK") {
          // [COREDUMP-TEST-ONCE, v3.31.10] Crash wykonujemy tylko po swiezym
          // uzbrojeniu. Po zapisaniu update_id test jest rozbrajany PRZED
          // crashem, wiec ta sama wiadomosc po restarcie nie wykona sie ponownie.
          if (!testCrashCzyUzbrojony()) {
            sendTelegramMessage(F("Test nie jest uzbrojony. Najpierw wpisz /testcrash, a potem w ciagu 60 s /testcrash TAK."));
          } else if (!testCrashOznaczUpdateZuzyty(updateId)) {
            g_testCrashArmed = false;
            sendTelegramMessage(F("Ten test zostal juz wykonany albo zostal zablokowany. Uzbroj ponownie przez /testcrash."));
          } else {
            g_testCrashArmed = false;
            sendTelegramMessage(F("Potwierdzono - restart za chwile."));
            wywolajTestowyCrash();
          }
        } else if (cmd == "/historia") {
          tgKolejkujAlboOdpowiedzBledem(TG_HIST);
        } else if (cmd == "/solar_tryb" || cmd.startsWith("/solar_tryb ")) {
          // [v3.52.7] Znacznik trybu instalacji — jedyny sposob, zeby odroznic
          // "zbiornik z woda, tylko pochmurno" od "woda spuszczona na zime".
          // Bez tego zimowe odczyty (czujnik w pustym zbiorniku mierzy
          // powietrze) wygladaja jak dane sloneczne z zerowym przyrostem.
          String arg = cmd.substring(strlen("/solar_tryb"));
          arg.trim();
          arg.toLowerCase();
          if (arg.length() == 0) {
            String o;
            o.reserve(420);
            o += F("Tryb instalacji: <b>");
            o += solarSeasonModeName();
            o += F("</b>\n");
            if (g_solarOffSeason) {
              o += F("Zbiornik na dachu jest pusty (ZIMA) — czujnik mierzy powietrze. "
                     "Prognoza GHI nie jest pobierana, a nowe dni sa oznaczane "
                     "w raporcie jako \"(poza sezonem)\".\n");
            } else {
              o += F("Zbiornik jest w obiegu — odczyty sa danymi slonecznymi, "
                     "a prognoza GHI pobierana.\n");
            }
            o += F("Zmiana: /solar_tryb spuszczona  albo  /solar_tryb sezon");
            sendTelegramMessage(o);
          } else if (arg == "spuszczona" || arg == "sezon") {
            const bool nowy = (arg == "spuszczona");
            if (nowy == g_solarOffSeason) {
              String o;
              o.reserve(160);
              o += F("Tryb juz ustawiony na <b>");
              o += solarSeasonModeName();
              o += F("</b> — nic nie zmienilem.");
              sendTelegramMessage(o);
            } else {
              g_solarOffSeason = nowy;
              config.putBool("solarOffSeason", nowy);
              String o;
              o.reserve(320);
              o += F("Tryb instalacji ustawiony na <b>");
              o += solarSeasonModeName();
              o += F("</b>.\n");
              if (nowy) {
                o += F("Prognoza GHI nie bedzie pobierana. Nowe rekordy dostana "
                       "znacznik \"(poza sezonem)\" — temperatura z pustego "
                       "zbiornika to nie dane sloneczne.\n");
                o += F("Zapis trwaly: przezyje restart i OTA.");
              } else {
                o += F("Woda w zbiorniku — prognoza GHI wraca przy najblizszym "
                       "oknie (23:30-23:59 na jutro, 00:00-04:59 na dzis).\n");
                o += F("Zapis trwaly: przezyje restart i OTA.");
              }
              sendTelegramMessage(o);
            }
          } else {
            sendTelegramMessage(F("Uzycie: /solar_tryb  (pokaz stan), "
                                  "/solar_tryb spuszczona  (ZIMA, woda spuszczona), "
                                  "/solar_tryb sezon  (woda w zbiorniku)."));
          }
        } else if (cmd.startsWith("/archiwum_usun ")) {
          // [v3.52.1] Usun JEDEN dzien: /archiwum_usun 2026-10-19
          String arg = cmd.substring(strlen("/archiwum_usun "));
          arg.trim();
          if (solar_daily::isValidDateKey(arg.c_str()) && arg.length() == 10) {
            strncpy(g_solarDeleteDate, arg.c_str(), sizeof(g_solarDeleteDate) - 1);
            g_solarDeleteDate[sizeof(g_solarDeleteDate) - 1] = 0;
            tgKolejkujAlboOdpowiedzBledem(TG_SOLAR_DELETE_DAY);
          } else {
            sendTelegramMessage(F("Podaj date: /archiwum_usun RRRR-MM-DD (np. /archiwum_usun 2026-10-19)"));
          }
        } else if (cmd == "/archiwum_czysc" || cmd == "/archiwum_czysc TAK") {
          // [v3.52.0] Usuwa TYLKO rekordy sprzed poprawki kanalu (schemaVersion
          // < 2, bojler pieca C.O.). Bez "TAK" nic nie kasuje — pokazuje liczbe.
          if (cmd == "/archiwum_czysc TAK") {
            tgKolejkujAlboOdpowiedzBledem(TG_SOLAR_PURGE_LEGACY, 1);
          } else {
            tgKolejkujAlboOdpowiedzBledem(TG_SOLAR_PURGE_LEGACY, 0);
          }
        } else if (cmd == "/archiwum" || cmd.startsWith("/archiwum ") ||
                   cmd == "/solar" || cmd.startsWith("/solar ")) {
          // [v3.51.0] Opcjonalny argument: liczba dni 1..30, domyslnie 7.
          uint32_t dni = 0;
          const int sp = cmd.indexOf(' ');
          if (sp > 0) {
            String arg = cmd.substring(sp + 1);
            arg.trim();
            const long v = arg.toInt();
            if (v >= 1 && v <= (long)kSolarReportMaxDays) dni = (uint32_t)v;
          }
          tgKolejkujAlboOdpowiedzBledem(TG_SOLAR_ARCHIVE, dni);
        } else if (cmd == "/archiwum_test") {
          // [v3.53.1] Dowod podzialu wiadomosci bez czekania miesiaca na 30 dni.
          tgKolejkujAlboOdpowiedzBledem(TG_SOLAR_ARCHIVE_TEST);
        } else if (cmd == "/reset_alarmy") {
          tgKolejkujAlboOdpowiedzBledem(TG_RESET_ALARMY);
        } else if (cmd == "/update") {
          tgKolejkujAlboOdpowiedzBledem(TG_UPDATE);
        } else if (cmd == "/update_panel") {
          tgKolejkujAlboOdpowiedzBledem(TG_UPDATE_PANEL);
        } else if (cmd.startsWith("/")) {
          // [v3.53.1] Do tej wersji literowka konczyla sie CISZA i wygladala
          // jak zawieszony bot (/archiwum30 zamiast /archiwum 30 — 2026-10-21).
          String odp = F("Nie znam komendy: ");
          odp += cmd.substring(0, 64);
          odp += F("\nWpisz /help — pokaze menu.");
          sendTelegramMessage(odp);
        }
      }
    }

    pos = chunkEnd;
  }
}

