static bool recoveryOtaMegaLaunchTask() {
  if (g_recoveryOtaMegaActive || g_finalMegaActive || g_stabilityMegaActive) return false;
  if (fbLoopWorkerZajety() || g_telemetryRequestActive || g_telemetryCompletionPending ||
      g_spoolRuntimeArmed || g_securityH2TaskRunning || g_rtdbIntegrationActive) return false;
  g_recoveryOtaMegaActive = true;
  BaseType_t created = xTaskCreatePinnedToCore(
      recoveryOtaMegaTaskFn, "recoveryOtaMega", 16384, nullptr, 1,
      &g_recoveryOtaMegaTaskHandle, 0);
  if (created != pdPASS) {
    g_recoveryOtaMegaActive = false;
    g_recoveryOtaMegaTaskHandle = nullptr;
    return false;
  }
  return true;
}

