static bool rtdbRangeReadAll(WiFiClientSecure &client, String &rawOut, uint32_t limitMs) {
  rawOut = "";
  rawOut.reserve(8192);
  const unsigned long start = millis();
  while (millis() - start < limitMs) {
    serwisujTWDTJesliZarejestrowany();
    int avail = client.available();
    while (avail > 0) {
      char buf[512];
      int want = avail > (int)sizeof(buf) ? (int)sizeof(buf) : avail;
      int n = client.read((uint8_t*)buf, want);
      if (n <= 0) break;
      if (rawOut.length() + (size_t)n > 8192U) {
        return false;
      }
      rawOut.concat(buf, (size_t)n);
      avail = client.available();
    }
    if (!client.connected() && client.available() == 0) break;
    vTaskDelay(pdMS_TO_TICKS(5));
  }
  return rawOut.length() > 0;
}

static bool rtdbExtractHttpBody(const String &raw, String &bodyOut, uint16_t &statusOut, String &errorOut) {
  bodyOut = "";
  statusOut = 0;
  errorOut = "";
  int lineEnd = raw.indexOf("\r\n");
  if (lineEnd < 0) {
    errorOut = "HTTP_HEADER_MISSING";
    return false;
  }
  String statusLine = raw.substring(0, lineEnd);
  int sp = statusLine.indexOf(' ');
  if (sp < 0 || statusLine.length() < (size_t)(sp + 4)) {
    errorOut = "HTTP_STATUS_MISSING";
    return false;
  }
  statusOut = (uint16_t)statusLine.substring(sp + 1, sp + 4).toInt();
  int bodyPos = raw.indexOf("\r\n\r\n");
  if (bodyPos < 0) {
    errorOut = "HTTP_BODY_SEPARATOR_MISSING";
    return false;
  }
  bodyOut = raw.substring(bodyPos + 4);
  if (statusOut != 200) {
    errorOut = String("HTTP_STATUS_") + String(statusOut);
    String compact = bodyOut;
    compact.replace("\r", " ");
    compact.replace("\n", " ");
    if (compact.length() > 180) compact.remove(180);
    if (compact.length()) errorOut += String(" body=") + compact;
    return false;
  }
  return true;
}

static bool rtdbTestQueryRange(const String &path, uint32_t startTs, uint32_t endTs,
                               String &payloadOut, String &errorOut) {
  payloadOut = "";
  errorOut = "";
  if (WiFi.status() != WL_CONNECTED) { errorOut = "WiFi_NOT_CONNECTED"; return false; }
  if (g_rtdbRangeWorkerRunning) { errorOut = "rangeWorkerBusy"; return false; }
  if (!(fbAppReady && fbApp.ready())) { errorOut = "firebaseNotReady"; return false; }

  const String token = fbApp.getToken();
  if (token.length() < 32) { errorOut = "idTokenMissing"; return false; }

  g_rtdbRangeWorker.requestPath = path;
  g_rtdbRangeWorker.token = token;
  g_rtdbRangeWorker.startTs = startTs;
  g_rtdbRangeWorker.endTs = endTs;
  g_rtdbRangeWorker.payload = "";
  g_rtdbRangeWorker.error = "";
  g_rtdbRangeWorker.done = false;
  g_rtdbRangeWorker.ok = false;
  g_rtdbRangeWorkerRunning = true;

  TaskHandle_t worker = nullptr;
  BaseType_t created = xTaskCreatePinnedToCore(rtdbRangeWorkerTaskFn, "rtdbRange", 8192,
                                                &g_rtdbRangeWorker, 1, &worker, 0);
  if (created != pdPASS) {
    g_rtdbRangeWorkerRunning = false;
    errorOut = "rangeWorkerCreateFail";
    return false;
  }

  const unsigned long waitStart = millis();
  const unsigned long waitLimit = 20000UL;
  while (millis() - waitStart < waitLimit) {
    serwisujTWDTJesliZarejestrowany();
    if (g_rtdbRangeWorker.done) break;
    vTaskDelay(pdMS_TO_TICKS(20));
  }

  if (!g_rtdbRangeWorker.done) {
    errorOut = "rangeWorkerTimeout";
    return false;
  }
  payloadOut = g_rtdbRangeWorker.payload;
  errorOut = g_rtdbRangeWorker.error;
  return g_rtdbRangeWorker.ok;
}

static void rtdbRangeWorkerTaskFn(void *param) {
  RtdbRangeWorkerCtx *ctx = (RtdbRangeWorkerCtx*)param;
  bool ok = false;
  String raw;
  String body;
  IPAddress resolved;
  WiFiClientSecure client;
  client.setCACert(FIREBASE_TLS_TRUST_CA);
  client.setTimeout(4);
  client.setHandshakeTimeout(4000);

  do {
    if (WiFi.status() != WL_CONNECTED) { ctx->error = "WiFi_NOT_CONNECTED"; break; }
    if (!wifiHostByNameZLimitem(FIREBASE_HOST, resolved, 5000UL)) { ctx->error = "DNS_FAIL"; break; }
    if (resolved == IPAddress(0,0,0,0)) { ctx->error = "DNS_ZERO_IP"; break; }

    if (ctx->token.length() < 32) { ctx->error = "idTokenMissing"; break; }

    String requestPath = ctx->requestPath;
    if (!requestPath.startsWith("/")) requestPath = String("/") + requestPath;
    requestPath += ".json?orderBy=%22ts%22&startAt=" + String(ctx->startTs) +
                   "&endAt=" + String(ctx->endTs) + "&auth=" + ctx->token;

    // Public Arduino-ESP32 overload: IP + explicit TLS hostname keeps certificate
    // hostname verification/SNI while avoiding a second implicit DNS lookup.
    int connected = client.connect(resolved, 443, FIREBASE_HOST, FIREBASE_TLS_TRUST_CA, nullptr, nullptr);
    if (!connected) { ctx->error = "TLS_CONNECT_FAIL"; break; }
    applyFbSockTimeouts(client, 8);

    const String request = String("GET ") + requestPath + " HTTP/1.1\r\n" +
                           "Host: " + FIREBASE_HOST + "\r\n" +
                           "Accept: application/json\r\n" +
                           "Connection: close\r\n\r\n";
    if (client.print(request) != request.length()) { ctx->error = "HTTP_WRITE_FAIL"; break; }

    if (!rtdbRangeReadAll(client, raw, 9000UL)) {
      ctx->error = "HTTP_READ_TIMEOUT_OR_TOO_LARGE";
      break;
    }
    uint16_t status = 0;
    if (!rtdbExtractHttpBody(raw, body, status, ctx->error)) break;
    if (body == "null") { ctx->error = "EMPTY_RESULT"; break; }
    ctx->payload = body;
    ok = true;
  } while (false);

  client.stop();
  ctx->ok = ok;
  __atomic_store_n(&ctx->done, true, __ATOMIC_RELEASE);
  __atomic_store_n(&g_rtdbRangeWorkerRunning, false, __ATOMIC_RELEASE);
  vTaskDelete(NULL);
}

