          case TG_FIREBASE_PROVISION: {
            // [REMOTE-FB-PROVISION] Komenda wykonywana w tgTask, czyli w tym
            // samym kontekscie, ktory obsluguje Firebase. Nie logujemy wartosci
            // credentiali. Dla bezpieczenstwa nie nadpisujemy aktywnej sesji
            // Firebase — provisioning wykonujemy tylko, gdy Firebase nie jest
            // aktualnie READY i nie ma porzuconego workera.
            String payload = tgQueuedText;
            int p1 = payload.indexOf('|');
            int p2 = (p1 >= 0) ? payload.indexOf('|', p1 + 1) : -1;
            int p3 = (p2 >= 0) ? payload.indexOf('|', p2 + 1) : -1;
            if (p1 <= 0 || p2 <= p1 + 1 || p3 <= p2 + 1) {
              sendTelegramMessage(F("FB-PROV: zly format. Uzyj /fbprov|API_KEY|EMAIL|PASSWORD"));
              break;
            }
            String api = payload.substring(p1 + 1, p2);
            String email = payload.substring(p2 + 1, p3);
            String pass = payload.substring(p3 + 1);
            api.trim(); email.trim(); pass.trim();
            const bool valid = api.length() >= 20 &&
                               email.indexOf('@') > 0 && email.length() <= 160 &&
                               pass.length() >= 8;
            if (!valid) {
              sendTelegramMessage(F("FB-PROV: odrzucono — nieprawidlowy API key/email/haslo."));
              break;
            }
            if (fbAppReady || fbApp.ready() || fbLoopWorkerZajety()) {
              sendTelegramMessage(F("FB-PROV: odmowa — Firebase jest aktywny albo poprzedni worker jeszcze pracuje. Nie zmieniam credentiali."));
              break;
            }
            fbConfig.begin("firebase", false);
            fbConfig.putString("api_key", api);
            fbConfig.putString("auth_email", email);
            fbConfig.putString("auth_pass", pass);
            fbConfig.end();

            // Stary obiekt UserAuth moze zawierac poprzedni credential.
            // W normalnym scenariuszu jest null (to wlasnie brak NVS), ale
            // usuwamy go bezpiecznie przed ponownym loadFirebaseConfig().
            if (fbUserAuth != nullptr) {
              delete fbUserAuth;
              fbUserAuth = nullptr;
            }
            g_fbAppInitialized = false;
            fbAppReady = false;
            loadFirebaseConfig();
            fbInitialize();
            sendTelegramMessage(F("FB-PROV: credential zapisany do NVS. Firebase inicjalizowany ponownie; sprawdz /status za 5-10 s."));
            break;
          }

