            if (alarmOgrzewanieWlaczone) { dezaktywujAlarmCO();    alarmOgrzewanieWlaczone = false; }
            if (alarmPanelWlaczone)      { dezaktywujAlarmPanelu(); alarmPanelWlaczone = false; }
